'Online_Store_Accounts' => 'Λογαριασμοί online καταστήματος',
'Customers_without_login_alert' => 'Αυτοί είναι οι πελάτες POS / περαστικοί πελάτες που δεν έχουν ακόμη λογαριασμό στο online κατάστημα. Χρησιμοποιήστε το "Εγγραφή λογαριασμού" για να δημιουργήσετε στοιχεία σύνδεσης (email + κωδικός πρόσβασης) ώστε ο πελάτης να μπορεί να συνδεθεί και να αγοράζει από το online κατάστημά σας.',
'Customers_with_login_alert' => 'Αυτοί οι πελάτες έχουν λογαριασμό στο online κατάστημα και μπορούν να συνδεθούν στο κατάστημά σας. Οι αλλαγές που γίνονται εδώ (email, κωδικός πρόσβασης, κατάσταση, αποκλεισμός) επηρεάζουν μόνο τη σύνδεσή τους στο online κατάστημα - όχι την εγγραφή πελάτη στο POS.',
'Assigned_Permissions' => 'Ανατεθειμένα δικαιώματα',

'Modules' => 'Λειτουργικές μονάδες',

'Resize_Product_Images' => 'Αλλαγή μεγέθους εικόνων προϊόντων',
'Resize_Product_Images_Help' => 'Σμίκρυνση των εικόνων προϊόντων, παραλλαγών και συλλογής κατά την αποθήκευση. Απενεργοποιήστε το για να αποθηκεύονται τα αρχεία στην αρχική τους ανάλυση (μεγαλύτερα αρχεία, πιο αργές σελίδες).',
'Product_Image_Max_Size' => 'Μέγιστο μέγεθος εικόνας προϊόντος',
'Product_Image_Max_Size_Help' => 'Η μεγαλύτερη πλευρά, σε pixel, στην οποία προσαρμόζονται οι αποθηκευμένες εικόνες προϊόντων. Η αναλογία διαστάσεων διατηρείται και οι μικρότερες εικόνες δεν μεγεθύνονται ποτέ.',

'Grid_View' => 'Κάρτες',
'Table_View' => 'Πίνακας',

'Image_Max_2MB' => 'Η εικόνα πρέπει να είναι έως 2 MB.',

'Units_Guide_Title' => 'Πώς λειτουργούν οι μονάδες',
'Units_Guide_Base' => 'Βασική μονάδα: αφήστε κενό το "Βασική μονάδα". Το απόθεμα μετράται πάντα σε αυτή τη μονάδα, για παράδειγμα Τεμάχιο.',
'Units_Guide_Sub' => 'Υπομονάδα: επιλέξτε "Βασική μονάδα" και, στη συνέχεια, χρησιμοποιήστε τα "Τελεστής" και "Τιμή πράξης" για να τη μετατρέψετε στη βασική μονάδα.',
'Units_Guide_Example_Multiply' => 'Παράδειγμα: ένα Κιβώτιο με βασική μονάδα Τεμάχιο, τελεστή * και τιμή 12. Η πώληση 1 Κιβωτίου αφαιρεί 12 Τεμάχια από το απόθεμα.',
'Units_Guide_Example_Divide' => 'Παράδειγμα: ένα Γραμμάριο με βασική μονάδα Κιλό, τελεστή / και τιμή 1000. Η πώληση 500 Γραμμαρίων αφαιρεί 0.5 Κιλό από το απόθεμα.',
'Units_Guide_Note' => 'Μόνο βασικές μονάδες μπορούν να επιλεγούν ως "Βασική μονάδα", και μια μονάδα δεν μπορεί να διαγραφεί όσο τη χρησιμοποιούν υπομονάδες.',

'Amount_Paid' => 'Ποσό που πληρώθηκε',
'Payment_Amounts_Help' => 'Το Ποσό που πληρώθηκε εξοφλεί το υπόλοιπο και μειώνει την Οφειλή. Το Ποσό που ελήφθη είναι τα μετρητά που δόθηκαν: χρησιμοποιείται μόνο για τον υπολογισμό των Ρέστων και δεν αλλάζει την Οφειλή.',

'Show_Tax_Desc' => 'Ο φόρος που εφαρμόζεται σε ολόκληρη την πώληση κατά την ολοκλήρωση, τυπωμένος ως ξεχωριστή γραμμή "Φόρος παραγγελίας" στα σύνολα.',
'Show_Items_Tax_Desc' => 'Το άθροισμα του φόρου κάθε προϊόντος, τυπωμένο ως γραμμή "Συνολικός φόρος ειδών". Όταν είναι ενεργό, το υποσύνολο εμφανίζεται χωρίς αυτούς τους φόρους.',
'Show_Discount_Desc' => 'Η έκπτωση που εφαρμόζεται σε ολόκληρη την πώληση (συμπεριλαμβανομένης τυχόν έκπτωσης από πόντους), τυπωμένη ως ξεχωριστή γραμμή στα σύνολα.',
'Show_Product_Discount_Desc' => 'Η έκπτωση κάθε προϊόντος, τυπωμένη κάτω από το αντίστοιχο προϊόν στη λίστα ειδών.',

'Receipt_Font_Family' => 'Γραμματοσειρά απόδειξης',
'Receipt_Font_Family_Desc' => 'Γραμματοσειρά για όλο το κείμενο της εκτυπωμένης απόδειξης. Η "Προεπιλογή" διατηρεί τις τυπικές γραμματοσειρές απόδειξης.',
'Receipt_Font_Size' => 'Μέγεθος γραμματοσειράς απόδειξης (px)',
'Receipt_Font_Size_Desc' => 'Μέγεθος κειμένου σε όλη την απόδειξη, από 8 έως 24 pixel. Αφήστε κενό για διατήρηση του προεπιλεγμένου μεγέθους.',
'Font_Default' => 'Προεπιλογή',

'Amount_Paid_Help' => 'Το ποσό που εφαρμόζεται σε αυτό το έγγραφο· μειώνει την υπόλοιπη Οφειλή.',
'Received_Amount_Help' => 'Τα μετρητά που δόθηκαν πραγματικά. Ό,τι υπερβαίνει το Ποσό που πληρώθηκε επιστρέφεται ως Ρέστα και δεν μειώνει την Οφειλή.',

'OpeningBalanceReceived' => 'Αρχικό υπόλοιπο που εισπράχθηκε',
'OpeningBalancePaid' => 'Αρχικό υπόλοιπο που πληρώθηκε',

'Customize_Profit' => 'Προσαρμογή κέρδους',
'Custom_Profit' => 'Προσαρμοσμένο κέρδος',
'Custom_Profit_Hint' => 'Επιλέξτε ποια ποσά προστίθενται ή αφαιρούνται για να δημιουργήσετε το δικό σας μέγεθος κέρδους. Η επιλογή σας αποθηκεύεται σε αυτή τη συσκευή.',
'Profit_Formula' => 'Τύπος κέρδους',
