'Service_Revenue' => 'Έσοδα υπηρεσιών',
'Service_Profit' => 'Κέρδος υπηρεσιών',
'Service_Parts_Cost' => 'Κόστος ανταλλακτικών υπηρεσιών',
'Taxes_Collected' => 'Φόροι που εισπράχθηκαν (Πωλήσεις)',
'Taxes_Paid' => 'Φόροι που καταβλήθηκαν (Αγορές)',
'Discounts_Given' => 'Εκπτώσεις που δόθηκαν (Πωλήσεις)',
'Discounts_Received' => 'Εκπτώσεις που ελήφθησαν (Αγορές)',
'Shipping_Charged' => 'Χρεωμένα έξοδα αποστολής (Πωλήσεις)',
'Shipping_Paid' => 'Καταβληθέντα έξοδα αποστολής (Αγορές)',
'Expenses_By_Category' => 'Έξοδα ανά κατηγορία',
'Daily_Trend' => 'Ημερήσια τάση',
'Additional_Information' => 'Πρόσθετες πληροφορίες',
'Warehouses_Tab_Help' => 'Διαχειριστείτε τις αποθήκες σας (καταστήματα/υποκαταστήματα). Κάθε αποθήκη έχει το δικό της απόθεμα και κάθε έγγραφο — πωλήσεις, αγορές, μεταφορές, προσαρμογές — καταγράφεται σε μία από αυτές.',
'Warehouse_Locations_Tab_Help' => 'Ορίστε θέσεις ραφιέρας / ραφιού σε κάθε αποθήκη (π.χ. Διάδρομος 2 – Ραφιέρα B). Αντιστοιχίστε τες σε προϊόντα για να φαίνεται πού είναι φυσικά αποθηκευμένα τα είδη.',
'Already_Converted' => 'Μετατράπηκε σε πώληση',
'Salesperson' => 'Πωλητής',
'Select_Salesperson' => 'Επιλογή πωλητή',
'You' => 'Εσείς',
'Enable_Pos_Salesperson_Switch' => 'Αλλαγή πωλητή κατά την ολοκλήρωση',
'Enable_Pos_Salesperson_Switch_Hint' => 'Εμφάνιση επιλογέα πωλητή στην οθόνη POS ώστε μια πώληση να αποδίδεται σε άλλον υπάλληλο χωρίς αποσύνδεση. Ο επιλεγμένος πωλητής αποθηκεύεται στο τιμολόγιο και χρησιμοποιείται στις αναφορές πωλήσεων· η ενεργή συνεδρία POS παραμένει αμετάβλητη.',

'Wallet_Payment_Method_Missing' => 'Λείπει η μέθοδος πληρωμής Πορτοφόλι',
'Wallet_Payment_Method_Missing_Help' => 'Δεν βρέθηκε μέθοδος πληρωμής με ακριβές όνομα "Wallet". Το μέσο πληρωμής πορτοφολιού του POS αντιστοιχίζεται με αυτό το όνομα, επομένως οι πελάτες δεν μπορούν να πληρώσουν με το πορτοφόλι τους μέχρι να προσθέσετε μια μέθοδο πληρωμής με όνομα "Wallet" εδώ:',

'Show_Previous_Dues_Line' => 'Εμφάνιση γραμμής προηγούμενων οφειλών',
'Show_Previous_Dues_Line_Desc' => 'Υπόλοιπο που όφειλε ο πελάτης πριν από αυτή την πώληση. Τυπώνεται μόνο όταν είναι μεγαλύτερο από μηδέν.',
'Show_Net_Balance_Line' => 'Εμφάνιση γραμμής καθαρού υπολοίπου',
'Show_Net_Balance_Line_Desc' => 'Προηγούμενες οφειλές συν ό,τι οφείλεται ακόμη σε αυτή την πώληση. Τυπώνεται μόνο όταν οι προηγούμενες οφειλές είναι μεγαλύτερες από μηδέν.',

'QZ_Tray_Printer' => 'QZ Tray (εκτυπωτής σε αυτόν τον υπολογιστή)',
'QZ_Printer_Name_Hint' => 'Το όνομα του εκτυπωτή όπως εμφανίζεται στον υπολογιστή που εκτελεί το QZ Tray. Αφήστε κενό για χρήση του προεπιλεγμένου εκτυπωτή αυτού του υπολογιστή. Κάντε κλικ στο ⟳ για εντοπισμό εκτυπωτών.',
'QZ_Not_Running' => 'Το QZ Tray δεν εκτελείται σε αυτόν τον υπολογιστή. Εγκαταστήστε το από το qz.io και κρατήστε το σε λειτουργία, και στη συνέχεια επιτρέψτε αυτόν τον ιστότοπο όταν το ζητήσει το QZ.',
'Detect_Printers' => 'Εντοπισμός εκτυπωτών',
'QZ_Download_Cert' => 'Λήψη πιστοποιητικού (override.crt)',
'QZ_Setup_Title' => 'Πώς να ρυθμίσετε την εκτύπωση μέσω QZ Tray (μία φορά, σε κάθε υπολογιστή που εκτυπώνει ετικέτες)',
'QZ_Step_Install' => '1. Εγκαταστήστε το QZ Tray σε αυτόν τον υπολογιστή — κατεβάστε το δωρεάν από το qz.io, εκκινήστε το και αφήστε το σε λειτουργία (βρίσκεται στην περιοχή ειδοποιήσεων στα Windows ή στη γραμμή μενού στο macOS).',
'QZ_Step_Connect' => '2. Συνδέστε τον εκτυπωτή ετικετών μέσω USB και ελέγξτε ότι είναι εγκατεστημένος στο λειτουργικό σύστημα (Windows: Ρυθμίσεις > Εκτυπωτές και σαρωτές — macOS: Ρυθμίσεις συστήματος > Εκτυπωτές και σαρωτές).',
'QZ_Step_Detect' => '3. Κάντε κλικ στο κουμπί ⟳ δίπλα στο "Όνομα εκτυπωτή" παραπάνω για να εντοπίσετε τους εκτυπωτές αυτού του υπολογιστή και, στη συνέχεια, επιλέξτε τον εκτυπωτή ετικετών. Αφήστε το πεδίο κενό για χρήση του προεπιλεγμένου εκτυπωτή του υπολογιστή.',
'QZ_Step_Cert' => '4. Για εκτύπωση χωρίς αναδυόμενο παράθυρο άδειας, κατεβάστε το παρακάτω πιστοποιητικό και αντιγράψτε το στον φάκελο εγκατάστασης του QZ Tray, μετονομασμένο σε override.crt (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray). Στη συνέχεια, κλείστε το QZ Tray και εκκινήστε το ξανά.',
'QZ_Step_Test' => '5. Κάντε κλικ στο "Εκτύπωση δοκιμαστικής ετικέτας" παρακάτω. Αν το QZ Tray ζητήσει άδεια, κάντε κλικ στο Allow — με εγκατεστημένο το πιστοποιητικό δεν θα ξαναρωτήσει.',
'QZ_Step_Save' => '6. Κάντε κλικ στο Υποβολή για να αποθηκεύσετε αυτές τις ρυθμίσεις. Οι ετικέτες από τη σελίδα Εκτύπωση barcode θα εκτυπώνονται πλέον απευθείας σε αυτόν τον εκτυπωτή, χωρίς το παράθυρο εκτύπωσης του προγράμματος περιήγησης.',
'QZ_Setup_Note' => 'Το QZ Tray εκτελείται στον υπολογιστή από τον οποίο περιηγείστε, οπότε λειτουργεί ακόμη και όταν το Stocky φιλοξενείται σε απομακρυσμένο διακομιστή. Κάθε υπολογιστής που εκτυπώνει ετικέτες χρειάζεται εγκατεστημένο το QZ Tray.',

// PWA settings tab — installable app identity
'PWA_Enabled' => 'Ενεργοποίηση εγκαταστάσιμης εφαρμογής',
'PWA_Enabled_Help' => 'Επιτρέπει στα προγράμματα περιήγησης να προσφέρουν εγκατάσταση αυτής της εφαρμογής σε τηλέφωνα, tablet και υπολογιστές, και διατηρεί αποθηκευμένες τις σελίδες εκτός σύνδεσης. Η απενεργοποίηση αφαιρεί την προτροπή εγκατάστασης παντού και εκκαθαρίζει την cache στην επόμενη επίσκεψη.',
'PWA_Identity' => 'Ταυτότητα εφαρμογής',
'PWA_Launch' => 'Εκκίνηση και εμφάνιση',
'PWA_App_Name' => 'Όνομα εφαρμογής',
'PWA_App_Name_Help' => 'Εμφανίζεται στην προτροπή εγκατάστασης και στη λίστα εφαρμογών. Αφήστε κενό για χρήση του ονόματος εφαρμογής από τις ρυθμίσεις Εμφάνισης.',
'PWA_Short_Name' => 'Σύντομο όνομα',
'PWA_Short_Name_Help' => 'Εμφανίζεται κάτω από το εικονίδιο στις αρχικές οθόνες, όπου τα μεγάλα ονόματα περικόπτονται. Αφήστε κενό για χρήση του τμήματος του ονόματος εφαρμογής πριν από το "|".',
'PWA_Description' => 'Περιγραφή',
'PWA_Description_Help' => 'Εμφανίζεται από ορισμένα καταστήματα εφαρμογών και παράθυρα εγκατάστασης.',
'PWA_Start_Url' => 'Σελίδα εκκίνησης',
'PWA_Start_Url_Help' => 'Η σελίδα στην οποία ανοίγει η εγκατεστημένη εφαρμογή, ως διαδρομή που ξεκινά με "/". Χρησιμοποιήστε /next/pos για εκκίνηση απευθείας στο POS.',
'PWA_Display_Mode' => 'Λειτουργία εμφάνισης',
'PWA_Display_Mode_Help' => 'Το standalone αποκρύπτει τη γραμμή του προγράμματος περιήγησης· το fullscreen αποκρύπτει επίσης τη γραμμή κατάστασης· το browser ανοίγει κανονική καρτέλα.',
'PWA_Orientation' => 'Προσανατολισμός',
'PWA_Theme_Color' => 'Χρώμα θέματος',
'PWA_Theme_Color_Help' => 'Χρωματίζει τις γραμμές συστήματος γύρω από την εγκατεστημένη εφαρμογή.',
'PWA_Background_Color' => 'Φόντο οθόνης εκκίνησης',
'PWA_Background_Color_Help' => 'Φόντο της οθόνης εκκίνησης που εμφανίζεται ενώ ξεκινά η εφαρμογή.',
'PWA_Preview' => 'Προεπισκόπηση',
'PWA_View_Manifest' => 'Προβολή αρχείου manifest',
'PWA_Reinstall_Notice' => 'Οι συσκευές που έχουν ήδη εγκαταστήσει την εφαρμογή διατηρούν το παλιό όνομα και εικονίδιο μέχρι να απεγκατασταθεί και να εγκατασταθεί ξανά.',

'Label_Render_Mode' => 'Απόδοση ετικέτας',
'Label_Render_Mode_Hint' => 'Πώς σχεδιάζεται η ετικέτα. Οι γραμματοσειρές εκτυπωτή είναι το ταχύτερο και δίνουν το πιο ευκρινές barcode, αλλά τυπώνουν μόνο βασικούς λατινικούς χαρακτήρες με τη γραμματοσειρά του εκτυπωτή. Η εικόνα προεπισκόπησης αναπαράγει ακριβώς τη σχεδίαση της ετικέτας σας — την επιλεγμένη γραμματοσειρά, οποιαδήποτε γλώσσα — όπως κάνει το εξειδικευμένο λογισμικό ετικετών.',
'Render_Native' => 'Γραμματοσειρές εκτυπωτή (ταχύτερο)',
'Render_Raster' => 'Εικόνα προεπισκόπησης (ακριβής σχεδίαση)',
'Label_Width_Mm' => 'Πλάτος ετικέτας (mm)',
'Label_Height_Mm' => 'Ύψος ετικέτας (mm)',
'Label_Size_Hint' => 'Το φυσικό μέγεθος ενός αυτοκόλλητου στο ρολό. Πρέπει να ταιριάζει ακριβώς με τις τοποθετημένες ετικέτες — λάθος μέγεθος κάνει τον εκτυπωτή να αναζητά το κενό σε λάθος σημείο, έτσι κάθε ετικέτα τυπώνεται όλο και πιο εκτός θέσης.',
'Calibrate_Labels' => 'Βαθμονόμηση ετικετών',
'Calibrate_Labels_Hint' => 'Ο εκτυπωτής τροφοδοτεί μερικές ετικέτες για να μετρήσει το αυτοκόλλητο και το κενό. Εκτελέστε το μία φορά μετά την τοποθέτηση νέου ρολού ή όταν οι θέσεις εκτύπωσης μετατοπίζονται.',
'Calibration_Sent' => 'Η βαθμονόμηση ξεκίνησε — ο εκτυπωτής θα τροφοδοτήσει μερικές κενές ετικέτες για να τις μετρήσει. Όταν σταματήσει, εκτελέστε δοκιμαστική εκτύπωση.',
'Label_Printer_Dpi' => 'Ανάλυση κεφαλής εκτύπωσης',
'Label_Printer_Dpi_Hint' => 'Οι περισσότεροι εκτυπωτές ετικετών είναι 203 dpi. Δεν είστε σίγουροι; Χρησιμοποιήστε το κουμπί "Εύρεση ανάλυσης" παρακάτω — τυπώνει την απάντηση.',
'Find_Resolution' => 'Εύρεση ανάλυσης',
'Find_Resolution_Hint' => 'Τυπώνει δύο ετικέτες, με σήμανση 203 και 300. Η σωστή εμφανίζει ένα πλήρες ορθογώνιο στο αυτοκόλλητο με μικρό, ομοιόμορφο περιθώριο σε όλες τις πλευρές· η λάθος έχει ελλιπή περιγράμματα ή επεκτείνεται στο επόμενο αυτοκόλλητο.',
'Dpi_Test_Sent' => 'Εκτυπώνονται δύο ετικέτες, με σήμανση 203 και 300. Η σωστή εμφανίζει ένα πλήρες ορθογώνιο με μικρό, ομοιόμορφο περιθώριο σε όλες τις πλευρές — ορίστε την "Ανάλυση κεφαλής εκτύπωσης" σε αυτόν τον αριθμό και αποθηκεύστε.',
'Label_Offset_X' => 'Οριζόντια μετατόπιση (mm)',
'Label_Offset_X_Hint' => 'Μετακινεί την εκτύπωση πλευρικά στο αυτοκόλλητο. Χρησιμοποιήστε το όταν το κείμενο κόβεται σε μία πλαϊνή άκρη — π.χ. 2.5 όταν το λευκό αυτοκόλλητο είναι κεντραρισμένο σε φαρδύτερο χαρτί υποστήριξης. Προσαρμόστε ανά 0.5.',
'Label_Offset_Y' => 'Κάθετη μετατόπιση (mm)',
'Label_Offset_Y_Hint' => 'Μετακινεί την εκτύπωση κατά μήκος της ετικέτας. Αυξήστε όταν το επάνω μέρος της σχεδίασης κόβεται ή λείπει· μειώστε όταν ξεκινά πολύ χαμηλά.',
