'Wholesale_Pricing_Variants_Hint' => 'Μία κλίμακα καλύπτει ολόκληρο το προϊόν: κάθε παραλλαγή πωλείται στην τιμή κλιμακίου μόλις η δική της γραμμή φτάσει ένα κλιμάκιο.',
