/* ---- Online orders guide (Store > Online Orders) ---- */
'Orders_Guide' => 'Οδηγός παραγγελιών',
'Ord_Guide_Intro' => 'Πώς μια παραγγελία από το online κατάστημά σας περνά στο απόθεμα και στους λογαριασμούς σας, και πού καταγράφονται πραγματικά τα χρήματα.',
'Ord_Guide_Lifecycle_Title' => 'Κατάσταση παραγγελίας',
'Ord_Guide_Lifecycle_Pending' => 'Νέα παραγγελία που περιμένει τον έλεγχό σας. Μόνο μια εκκρεμής παραγγελία μπορεί να επιβεβαιωθεί ή να ακυρωθεί.',
'Ord_Guide_Lifecycle_Confirmed' => 'Αποδεχτήκατε την παραγγελία. Το Stocky δημιουργεί μια Πώληση στην αποθήκη που επιλέξατε και αφαιρεί το απόθεμα — αυτή η πώληση είναι η εγγραφή από την οποία διαβάζουν οι αναφορές αποθέματος, πληρωμών και κερδών.',
'Ord_Guide_Lifecycle_Shipped' => 'Αποστείλατε την παραγγελία. Μόνο εκτέλεση: το απόθεμα είχε ήδη αφαιρεθεί κατά την επιβεβαίωση.',
'Ord_Guide_Lifecycle_Delivered' => 'Ο πελάτης παρέλαβε την παραγγελία. Από αυτό ξεκινά η περίοδος επιστροφής.',
'Ord_Guide_Lifecycle_Cancelled' => 'Η παραγγελία ακυρώθηκε πριν από την επιβεβαίωση, οπότε δεν δημιουργήθηκε πώληση και δεν αφαιρέθηκε απόθεμα.',
'Ord_Guide_PaymentStatus_Tip' => 'Ορίζεται κατά την ολοκλήρωση αγοράς και δεν επεξεργάζεται εδώ. Κάντε κλικ για να δείτε πώς να καταγράψετε την πληρωμή.',
'Ord_Guide_Payment_Title' => 'Κατάσταση πληρωμής',
'Ord_Guide_Payment_Intro' => 'Αυτή η στήλη καταγράφει πώς επέλεξε ο πελάτης να πληρώσει κατά την ολοκλήρωση αγοράς. Ορίζεται από το κατάστημα και δεν μπορεί να επεξεργαστεί από αυτή τη σελίδα — τα ίδια τα χρήματα παρακολουθούνται στην πώληση που δημιουργεί η επιβεβαίωση της παραγγελίας.',
'Ord_Guide_Payment_Paid' => 'Ο πελάτης έχει ήδη πληρώσει online μέσω πύλης πληρωμών. Η επιβεβαίωση της παραγγελίας δημιουργεί την πώληση ως Εξοφλημένη και καταγράφει την πληρωμή για εσάς — δεν χρειάζεται τίποτε άλλο.',
'Ord_Guide_Payment_Pending' => 'Αντικαταβολή, τραπεζική μεταφορά ή άλλη μέθοδος μεταγενέστερης πληρωμής. Η επιβεβαίωση της παραγγελίας δημιουργεί την πώληση ως Ανεξόφλητη, οπότε καταγράφετε εσείς τα χρήματα μόλις τα εισπράξετε — δείτε τα παρακάτω βήματα.',
'Ord_Guide_Payment_Failed' => 'Η πύλη απέρριψε την πληρωμή ή ο πελάτης την εγκατέλειψε. Η παραγγελία ακυρώνεται αυτόματα.',
'Ord_Guide_MarkPaid_Title' => 'Αλλαγή πληρωμής από εκκρεμή σε εξοφλημένη',
'Ord_Guide_MarkPaid_Step1' => 'Επιβεβαιώστε πρώτα την παραγγελία εδώ — η επιβεβαίωση είναι αυτή που δημιουργεί την πώληση.',
'Ord_Guide_MarkPaid_Step2' => 'Ανοίξτε Πωλήσεις > Όλες οι πωλήσεις και βρείτε αυτή την πώληση (ίδιος πελάτης, και η σελίδα λεπτομερειών δείχνει την online παραγγελία από την οποία προήλθε).',
'Ord_Guide_MarkPaid_Step3' => 'Ανοίξτε το μενού ενεργειών της γραμμής και επιλέξτε Δημιουργία πληρωμής.',
'Ord_Guide_MarkPaid_Step4' => 'Εισαγάγετε το ποσό, τη μέθοδο πληρωμής και την ημερομηνία και, στη συνέχεια, αποθηκεύστε. Η πώληση μεταβαίνει αυτόματα σε Μερική ή Εξοφλημένη, ανάλογα με το ποσό.',
'Ord_Guide_MarkPaid_Note' => 'Η Κατάσταση πληρωμής που εμφανίζεται εδώ συνεχίζει να καταγράφει την επιλογή κατά την ολοκλήρωση αγοράς και παραμένει ως έχει. Η πώληση είναι η λογιστική εγγραφή και τροφοδοτεί τις αναφορές πληρωμών και κερδών. Χρησιμοποιήστε την Εμφάνιση πληρωμών στην πώληση για να ελέγξετε ή να επεξεργαστείτε όσα καταχωρίσατε.',
'Ord_Guide_Notes_Title' => 'Καλό να γνωρίζετε',
'Ord_Guide_Note_Warehouse' => 'Η αποθήκη που επιλέγετε κατά την επιβεβαίωση καθορίζει από πού αφαιρείται το απόθεμα. Οι αποθήκες που δεν μπορούν να καλύψουν ολόκληρη την παραγγελία επισημαίνονται ως Εκτός αποθέματος σε αυτή τη λίστα.',
'Ord_Guide_Note_Preorder' => 'Τα είδη προπαραγγελίας παρακάμπτουν τον έλεγχο αποθέματος, οπότε μια παραγγελία που τα περιέχει μπορεί να επιβεβαιωθεί ακόμη και όταν η ποσότητα δεν είναι ακόμη διαθέσιμη.',
'Ord_Guide_Note_Flagged' => 'Η ετικέτα Επισημασμένο σημαίνει ότι η παραγγελία ενεργοποίησε έλεγχο απάτης κατά την ολοκλήρωση αγοράς. Τοποθετήστε τον δείκτη πάνω στην ετικέτα για να δείτε την αιτία και ελέγξτε την παραγγελία πριν την επιβεβαιώσετε.',
'Ord_Guide_Note_Cancel' => 'Η ακύρωση είναι δυνατή μόνο όσο η παραγγελία εκκρεμεί. Μόλις επιβεβαιωθεί, αναστρέψτε την μέσω της πώλησης ή μιας επιστροφής πελάτη.',


