// Variants guide drawer (product form).
'Guide' => 'Οδηγός',
'Variants_Guide' => 'Οδηγός παραλλαγών',
'VG_Intro' => 'Ένα προϊόν με παραλλαγές πωλείται ως πολλές παραλλαγές. Δημιουργήστε τες από επιλογές (συνιστάται) ή ως απλή λίστα ονομάτων. Κάθε παραλλαγή έχει δικό της κωδικό, τιμές, εικόνα και απόθεμα.',
'VG_Options_Title' => 'Λειτουργία επιλογών (Χρώμα, Μέγεθος...)',
'VG_Opt_Step1' => 'Κρατήστε τον διακόπτη στην κεφαλίδα της κάρτας στο "Επιλογές".',
'VG_Opt_Step2' => 'Πληκτρολογήστε ένα όνομα επιλογής όπως Χρώμα ή Μέγεθος ή επιλέξτε μία από τις προτάσεις.',
'VG_Opt_Step3' => 'Πληκτρολογήστε μια τιμή (για παράδειγμα Κόκκινο) και πατήστε Enter. Επαναλάβετε για κάθε τιμή· το κόμμα διαχωρίζει επίσης τις τιμές. Κάντε κλικ στο x μιας τιμής για να την αφαιρέσετε.',
'VG_Opt_Step4' => 'Κάντε κλικ στο "Προσθήκη επιλογής" για δεύτερη ή τρίτη επιλογή (έως 3 επιλογές).',
'VG_Opt_Step5' => 'Κάντε κλικ στο "Δημιουργία παραλλαγών". Δημιουργείται μία γραμμή ανά συνδυασμό και το όνομά της σχηματίζεται αυτόματα, για παράδειγμα "Red / S".',
'VG_Opt_Step6' => 'Εισαγάγετε κόστος και τιμή σε κάθε γραμμή ή πληκτρολογήστε μια τιμή στο "Εφαρμογή σε όλα" και κάντε κλικ στο Κόστος ή Τιμή για να την αντιγράψετε σε κάθε γραμμή.',
'VG_Opt_Step7' => 'Οι κωδικοί δημιουργούνται για εσάς. Πληκτρολογήστε τον δικό σας ή κάντε κλικ στο εικονίδιο ανανέωσης για να δημιουργήσετε άλλον.',
'VG_Opt_Step8' => 'Προαιρετικό: επιλέξτε "Δείγματα χρωμάτων" σε μια επιλογή και διαλέξτε χρώμα για κάθε τιμή· το κατάστημα το εμφανίζει ως χρωματιστή κουκκίδα.',
'VG_Rows_Title' => 'Γραμμές παραλλαγών',
'VG_Rows_Text' => 'Κάθε γραμμή έχει εικόνα, κωδικό, barcode, κόστος, τιμή, τιμή χονδρικής και ελάχιστη τιμή πώλησης. Κατά τη δημιουργία προϊόντος μπορείτε επίσης να εισαγάγετε το αρχικό απόθεμα ανά αποθήκη για κάθε παραλλαγή. Η ετικέτα "Ημιτελές" σημαίνει ότι στη γραμμή λείπει τιμή για μία επιλογή.',
'VG_List_Title' => 'Λειτουργία απλής λίστας',
'VG_List_Text' => 'Πληκτρολογήστε ένα όνομα παραλλαγής και πατήστε Enter (ή κάντε κλικ στο Προσθήκη) για να προσθέσετε γραμμή και, στη συνέχεια, συμπληρώστε τον κωδικό και τις τιμές της. Αυτή είναι η κλασική συμπεριφορά και παραμένει διαθέσιμη για τα υπάρχοντα προϊόντα.',
'VG_Edit_Title' => 'Μεταγενέστερη επεξεργασία',
'VG_Edit_1' => 'Προσθέστε μια τιμή και κάντε κλικ στο "Δημιουργία παραλλαγών": προστίθενται μόνο οι συνδυασμοί που λείπουν. Οι υπάρχουσες γραμμές διατηρούν τους κωδικούς, τις τιμές και το ιστορικό τους.',
'VG_Edit_2' => 'Η αφαίρεση μιας τιμής ή μιας επιλογής αφαιρεί τις γραμμές που τη χρησιμοποιούν. Οι ήδη αποθηκευμένες γραμμές διαγράφονται όταν αποθηκεύσετε το προϊόν, μετά από επιβεβαίωση.',
'VG_Edit_3' => 'Μια παραλλαγή που έχει ακόμη απόθεμα δεν μπορεί να αφαιρεθεί. Προσαρμόστε ή μεταφέρετε πρώτα το απόθεμά της.',
'VG_Edit_4' => 'Η μετάβαση στην "Απλή λίστα" διατηρεί τις γραμμές και τα ονόματά τους, αλλά απορρίπτει τους ορισμούς επιλογών.',
'VG_Store_Title' => 'Στο online κατάστημα',
'VG_Store_Text' => 'Οι πελάτες επιλέγουν μία τιμή ανά επιλογή, για παράδειγμα Χρώμα και μετά Μέγεθος. Οι συνδυασμοί που δεν υπάρχουν απενεργοποιούνται και όσοι είναι εκτός αποθέματος εμφανίζονται διαγραμμένοι. Η επιλεγμένη παραλλαγή είναι αυτή που μπαίνει στο καλάθι.',
'Choose_Source' => 'Επιλογή πηγής',
'Portal_Request' => 'Αίτημα πύλης',
'Portal_Quotation_Requests' => 'Αιτήματα προσφοράς από την πύλη',
'Warehouse_Invoice_Address_Help' => 'Διεύθυνση που τυπώνεται στα τιμολόγια που εκδίδει αυτή η αποθήκη. Αφήστε κενό για χρήση της διεύθυνσης της εταιρείας από τις ρυθμίσεις.',
'Warehouse_Logo_Help' => 'Λογότυπο που τυπώνεται στα τιμολόγια και τις αποδείξεις POS αυτής της αποθήκης. Αφήστε κενό για χρήση του λογότυπου της εταιρείας.',
'Warehouse_Invoice_Footer_Help' => 'Επιπλέον σημείωση που τυπώνεται στο κάτω μέρος των τιμολογίων που εκδίδει αυτή η αποθήκη.',
'Issued_By' => 'Εκδόθηκε από',
'Enable_Warehouse_Letterhead' => 'Επιστολόχαρτο αποθήκης στα τιμολόγια',
'Enable_Warehouse_Letterhead_Hint' => 'Εκτύπωση της εκδούσας αποθήκης στα τιμολόγια, τις αποδείξεις POS και τη δημόσια σελίδα τιμολογίου: το όνομά της αντικαθιστά την επωνυμία της εταιρείας, και η διεύθυνση, το τηλέφωνο, το email, το λογότυπο και η σημείωση υποσέλιδου αντικαθιστούν τα αντίστοιχα της εταιρείας. Κάθε πεδίο που μένει κενό στην αποθήκη επιστρέφει στις γενικές ρυθμίσεις της εταιρείας.',
'Warehouse_Letterhead_Receipt_Notice' => 'Το Επιστολόχαρτο αποθήκης είναι ενεργό: το όνομα καταστήματος, η διεύθυνση και το τηλέφωνο που τυπώνονται σε πραγματική απόδειξη προέρχονται από την αποθήκη που εξέδωσε την πώληση, και η σημείωση υποσέλιδου προστίθεται κάτω από τη σημείωση πελάτη.',
'Warehouse_Letterhead_Receipt_Demo' => 'Σημείωση υποσέλιδου υποκαταστήματος — ορίζεται ανά αποθήκη στις Αποθήκες.',
