'Closing_Balance' => 'Τελικό υπόλοιπο',
'Shopify_Link_Card_Hint' => 'Συνδέστε αυτό το προϊόν με μια καταχώριση που υπάρχει ήδη στο κατάστημά σας, ώστε ο συγχρονισμός να την ενημερώνει αντί να δημιουργεί δεύτερη.',
