'Upd_Manual_Step_Done' => 'Τελειώσατε! Απολαύστε την ενημερωμένη εφαρμογή.',
'Upd_Note_Blank_Pages' => 'Σημείωση: Αν κάποιες σελίδες δεν φορτώνουν ή είναι κενές, βεβαιωθείτε ότι έχετε καθαρίσει τη μνήμη cache του προγράμματος περιήγησης.',
'Upd_Guide_Before_Title' => '1. Πριν από την ενημέρωση',
'Upd_Guide_Before_Download' => 'Κατεβάστε το {package} της εφαρμογής από τον λογαριασμό σας στο CodeCanyon ({path}). Μην το αποσυμπιέσετε — το πρόγραμμα ενημέρωσης χρειάζεται το ZIP ακριβώς όπως κατέβηκε.',
'Upd_Latest_Full_Zip' => 'πιο πρόσφατο πλήρες πακέτο ZIP',
'Upd_Guide_Before_Admin' => 'Βεβαιωθείτε ότι έχετε συνδεθεί ως διαχειριστής με το δικαίωμα {perm}. Κανείς άλλος δεν μπορεί να δει ή να εκτελέσει το πρόγραμμα ενημέρωσης.',
'Upd_Guide_Before_Quiet' => 'Επιλέξτε μια ήσυχη στιγμή: κατά την ενημέρωση η εφαρμογή μεταβαίνει σε λειτουργία συντήρησης για λίγο και οι άλλοι χρήστες δεν έχουν πρόσβαση.',
'Upd_Guide_Before_No_Manual' => '{not} χρειάζεται να κάνετε χειροκίνητο αντίγραφο ασφαλείας, να αποσυμπιέσετε αρχεία, να εκτελέσετε εντολές, να επεξεργαστείτε αρχεία ρυθμίσεων ή να αγγίξετε τη βάση δεδομένων — το πρόγραμμα ενημέρωσης τα κάνει όλα αυτόματα. (Ένα επιπλέον χειροκίνητο αντίγραφο ασφαλείας φυσικά δεν βλάπτει ποτέ.)',
'Upd_Not' => 'ΔΕΝ',
'Upd_Guide_Code_Overwritten' => 'Αν έχετε τροποποιήσει χειροκίνητα τον κώδικα της εφαρμογής, οι αλλαγές σας θα αντικατασταθούν από την ενημέρωση. Τα δεδομένα, οι μεταφορτώσεις, οι ρυθμίσεις και το .env σας διατηρούνται πάντα.',
'Upd_Guide_Running_Title' => '2. Εκτέλεση της ενημέρωσης',
'Upd_Guide_Run_Open' => 'Ανοίξτε το {path} (αυτή τη σελίδα) και μείνετε στην καρτέλα {tab}.',
'Upd_Guide_Run_Upload' => '{upload}: κάντε κλικ ή σύρετε το πακέτο που κατεβάσατε στο πλαίσιο μεταφόρτωσης. Τα μεγάλα αρχεία μεταφορτώνονται σε μικρά τμήματα, οπότε λειτουργεί και σε κοινόχρηστη φιλοξενία με χαμηλά όρια μεταφόρτωσης. Ένα checksum προστατεύει από κατεστραμμένες ή ελλιπείς μεταφορτώσεις.',
'Upd_Upload_The_Zip' => 'Μεταφορτώστε το ZIP',
'Upd_Guide_Run_Validation' => '{auto} μετά τη μεταφόρτωση (μπορείτε να τον εκτελέσετε ξανά με το κουμπί {button}). Το σύστημα ελέγχει: ακεραιότητα ZIP, δομή και πληρότητα πακέτου, συμβατότητα έκδοσης (οι υποβαθμίσεις απορρίπτονται), απαιτούμενη έκδοση PHP και επεκτάσεις, δικαιώματα αρχείων, ελεύθερο χώρο δίσκου, σύνδεση βάσης δεδομένων, ρυθμίσεις, και ότι δεν εκτελείται άλλη ενημέρωση.',
'Upd_Validation_Runs_Automatically' => 'Ο έλεγχος εκτελείται αυτόματα',
'Upd_Guide_Run_Review' => 'Ελέγξτε το πλαίσιο {panel}. Το κουμπί {button} εμφανίζεται μόνο όταν περάσουν όλοι οι κρίσιμοι έλεγχοι. Αν ένας έλεγχος αποτύχει, το μήνυμα σας λέει ακριβώς τι πρέπει να διορθώσετε.',
'Upd_Guide_Run_Click' => 'Κάντε κλικ στο {button} και επιβεβαιώστε. Στη συνέχεια απλώς {keep} και παρακολουθήστε τη γραμμή προόδου. Το σύστημα εκτελεί, με τη σειρά:',
'Upd_Keep_Page_Open' => 'κρατήστε αυτή τη σελίδα ανοιχτή',
'Upd_Guide_Phase_Backup' => '{label} — δημιουργούνται και {verified} ένα πλήρες αντίγραφο της βάσης δεδομένων, ένα ZIP κάθε αρχείου της εφαρμογής που μπορεί να αλλάξει η ενημέρωση και ένα αντίγραφο του {env}. Οι μεταφορτώσεις σας ({images}) και το {storage} δεν αγγίζονται ποτέ από μια ενημέρωση, οπότε δεν αρχειοθετούνται. Αν δεν είναι δυνατή η δημιουργία αντιγράφου ασφαλείας, η ενημέρωση σταματά εδώ και τίποτα δεν αλλάζει.',
'Upd_Verified' => 'επαληθεύονται',
'Upd_Guide_Phase_Prepare' => '{label} — η νέα έκδοση αποσυμπιέζεται σε χώρο προετοιμασίας και ελέγχεται ξανά. Η ζωντανή εφαρμογή παραμένει ανέγγιχτη.',
'Upd_Guide_Phase_Maintenance' => '{label} — ενεργοποιείται η λειτουργία συντήρησης· οι επισκέπτες βλέπουν μια φιλική οθόνη «Επιστρέφουμε σύντομα».',
'Upd_Guide_Phase_Files' => '{label} — τα νέα αρχεία τοποθετούνται σχεδόν ακαριαία· τα παλιά αρχεία φυλάσσονται για επαναφορά. Οι προστατευμένες διαδρομές ({env}, {storage}, {images}) δεν αντικαθίστανται ποτέ.',
'Upd_Guide_Phase_Database' => '{label} — εκτελούνται τα migrations και στη συνέχεια ανανεώνονται τα δικαιώματα, οι μεταφράσεις και τα πρότυπα.',
'Upd_Guide_Phase_Cache' => '{label} — όλες οι μνήμες cache καθαρίζονται και αναδημιουργούνται.',
'Upd_Guide_Phase_Verify' => '{label} — έλεγχοι υγείας επιβεβαιώνουν ότι η νέα έκδοση εκκινεί, η βάση δεδομένων λειτουργεί, όλα τα migrations εκτελέστηκαν και οι ρυθμίσεις είναι έγκυρες.',
'Upd_Guide_Phase_Done' => '{label} — η λειτουργία συντήρησης απενεργοποιείται και τα προσωρινά αρχεία καθαρίζονται.',
'Upd_Guide_Run_Success' => 'Όταν δείτε {success}, κάντε κλικ στο {reload} και κάντε πλήρη ανανέωση του προγράμματος περιήγησης ({keys}) ώστε να φορτωθούν τα νέα αρχεία του πίνακα διαχείρισης.',
'Upd_Update_Successful_Short' => 'Επιτυχής ενημέρωση',
'Upd_Guide_No_Internet' => 'Δεν απαιτείται σύνδεση στο διαδίκτυο κατά την ενημέρωση — όλα προέρχονται από το μεταφορτωμένο ZIP. Η απώλεια σύνδεσης ή το κλείσιμο του προγράμματος περιήγησης ΔΕΝ χαλάει την ενημέρωση: ο διακομιστής θυμάται ακριβώς πού σταμάτησε.',
'Upd_Guide_Wrong_Title' => '3. Αν κάτι πάει στραβά',
'Upd_Guide_Wrong_Rollback' => '{label} — αν κάτι αποτύχει αφού άρχισαν να αλλάζουν αρχεία (σφάλμα αποσυμπίεσης, αποτυχία migration, αποτυχημένος έλεγχος υγείας, γεμάτος δίσκος, …), το σύστημα επαναφέρει αυτόματα τα προηγούμενα αρχεία και τη βάση δεδομένων από το επαληθευμένο αντίγραφο ασφαλείας, απενεργοποιεί τη λειτουργία συντήρησης και αναφέρει {message}. Επιστρέφετε ακριβώς εκεί από όπου ξεκινήσατε.',
'Upd_Automatic_Rollback' => 'Αυτόματη επαναφορά',
'Upd_Failed_Previous_Restored' => 'Η ενημέρωση απέτυχε — η προηγούμενη έκδοση επαναφέρθηκε',
'Upd_Guide_Wrong_Interrupted' => '{label} (επανεκκίνηση διακομιστή, λήξη χρόνου, κλειστό πρόγραμμα περιήγησης, διακοπή ρεύματος) — όταν ανοίξετε ξανά αυτή τη σελίδα, ένα κόκκινο banner προσφέρει δύο ασφαλείς επιλογές: {resume} (συνεχίζει από το ακριβές βήμα όπου σταμάτησε) ή {rollback} (επαναφέρει την προηγούμενη έκδοση από το αντίγραφο ασφαλείας).',
'Upd_Interrupted_Update' => 'Διακοπείσα ενημέρωση',
'Upd_Guide_Wrong_Unreachable' => '{label} — χρησιμοποιήστε την αυτόνομη {console} στο {path}. Λειτουργεί ακόμη και όταν ο ιστότοπος είναι σε λειτουργία συντήρησης ή τα αρχεία του πίνακα διαχείρισης είναι χαλασμένα, και προσφέρει τις ίδιες ενέργειες Συνέχεια / Επαναφορά. Υπάρχει επίσης ένας διακριτικός σύνδεσμος «Πρόσβαση διαχειριστή» στο κάτω μέρος της οθόνης συντήρησης.',
'Upd_Admin_Unreachable' => 'Ο πίνακας διαχείρισης δεν είναι προσβάσιμος',
'Upd_Recovery_Console' => 'κονσόλα ανάκτησης',
'Upd_Guide_Wrong_Locked_Out' => '{label} — όσο εκτελείται μια ενημέρωση, αυτή η σελίδα εμφανίζει έναν {link}. Αποθηκεύστε τον αν χρειαστεί να επιστρέψετε (για παράδειγμα αφού λήξει η συνεδρία σας)· σας επιτρέπει να περάσετε την οθόνη συντήρησης ώστε να συνδεθείτε ξανά.',
'Upd_Locked_Out_Maintenance' => 'Κλειδωμένος έξω λόγω λειτουργίας συντήρησης',
'Upd_Bypass_Link' => 'σύνδεσμο παράκαμψης',
'Upd_Guide_Wrong_Concurrent' => '{label} — θα δει {message} Μόνο μία ενημέρωση μπορεί να εκτελείται κάθε φορά.',
'Upd_Another_Admin_Updating' => 'Άλλος διαχειριστής προσπαθεί να ενημερώσει ταυτόχρονα',
'Upd_Guide_Backups_Title' => '4. Αντίγραφα ασφαλείας & επαναφορά',
'Upd_Guide_Backups_Created' => 'Κάθε ενημέρωση δημιουργεί αντίγραφο ασφαλείας {before} αγγίξει οτιδήποτε: όλα τα αρχεία της εφαρμογής που μπορεί να αντικαταστήσει η ενημέρωση, ένα αντίγραφο του {env} και ένα πλήρες αντίγραφο της βάσης δεδομένων. Οι μεταφορτώσεις και το {storage} δεν τροποποιούνται ποτέ από μια ενημέρωση και επομένως δεν περιλαμβάνονται — κρατήστε δικά σας αντίγραφα ασφαλείας για αυτά. Τα αντίγραφα ασφαλείας βρίσκονται στο {path} και δεν είναι ποτέ προσβάσιμα από το διαδίκτυο.',
'Upd_Before' => 'πριν',
'Upd_Guide_Backups_Panel' => 'Το πλαίσιο {panel} στην καρτέλα {tab} τα εμφανίζει με ημερομηνία, έκδοση και μέγεθος. Από εκεί μπορείτε να {restore} οποιοδήποτε πλήρες αντίγραφο ασφαλείας (αρχεία + βάση δεδομένων — λαμβάνεται πρώτα αντίγραφο ασφαλείας της τρέχουσας βάσης δεδομένων) ή να {delete} τα παλιά.',
'Upd_Restore_Verb' => 'επαναφέρετε',
'Upd_Delete_Verb' => 'διαγράψετε',
'Upd_Guide_Backups_Retention' => 'Χρησιμοποιήστε το {keep} για να επιλέξετε πόσα αντίγραφα ασφαλείας διατηρούνται· τα παλαιότερα αφαιρούνται αυτόματα μετά από κάθε επιτυχή ενημέρωση. Το μοναδικό εναπομείναν πλήρες αντίγραφο ασφαλείας δεν μπορεί ποτέ να διαγραφεί — έχετε πάντα δρόμο επιστροφής.',
'Upd_Guide_Manual_Title' => '5. Χειροκίνητη ενημέρωση (εναλλακτική μέθοδος)',
'Upd_Guide_Manual_Text' => 'Αν προτιμάτε να ενημερώνετε χειροκίνητα ή το πρόγραμμα μεταφόρτωσης δεν μπορεί να χρησιμοποιηθεί στον διακομιστή σας, ακολουθήστε τις αναλυτικές οδηγίες στην καρτέλα {tab} αυτής της σελίδας.',
'Upd_Guide_Clear_Cache_First' => 'Αν οι σελίδες φαίνονται χαλασμένες ή κενές μετά από οποιαδήποτε ενημέρωση, καθαρίστε πρώτα τη μνήμη cache του προγράμματος περιήγησης — σχεδόν πάντα αυτή είναι η αιτία.',
'Upd_Restore_Backup_Confirm' => 'Επαναφορά αυτού του αντιγράφου ασφαλείας; Τα τρέχοντα αρχεία και η τρέχουσα βάση δεδομένων θα αντικατασταθούν από το αντίγραφο ασφαλείας. Λαμβάνεται πρώτα αντίγραφο ασφαλείας της τρέχουσας βάσης δεδομένων. (v{version} — {date})',
'Woo_Guide_Lead' => 'Πώς ένα κατάστημα WooCommerce παραμένει συγχρονισμένο με το ERP. Οι γραμμές cron παρακάτω έχουν δημιουργηθεί για αυτόν τον διακομιστή, οπότε μπορούν να αντιγραφούν απευθείας σε αυτόν.',
'Woo_Guide_Ways_Note' => 'Σε αντίθεση με το Shopify, το WooCommerce δεν στέλνει τίποτα στο ERP από μόνο του — δεν υπάρχει δέκτης webhook εδώ, οπότε ό,τι έρχεται {in} φτάνει σύμφωνα με το πρόγραμμα. Μόνο το απόθεμα που φεύγει {out} μπορεί να είναι άμεσο.',
'Woo_In' => 'προς τα μέσα',
'Woo_Out' => 'προς τα έξω',
'Woo_Guide_Both_Ways_Title' => 'Και οι δύο κατευθύνσεις χρειάζονται πρώτα αυτό',
'Woo_Api_Keys' => 'Κλειδιά API',
'Woo_Guide_Api_Keys_Text' => '{path}, δικαίωμα {perm}. Αντιγράψτε το consumer key και το secret στην καρτέλα {settings}, μαζί με το URL του καταστήματος — τη διεύθυνση του ιστότοπού σας χωρίς κάθετο στο τέλος, π.χ. {example}.',
'Woo_Credentials_Saved' => 'τα διαπιστευτήρια αποθηκεύτηκαν',
'Woo_Not_Configured_Yet' => 'δεν έχει ρυθμιστεί ακόμη',
'Woo_Guide_Wp_App_Password_Title' => 'Κωδικός εφαρμογής WordPress (προαιρετικό)',
'Woo_Guide_Wp_App_Password_Text' => 'Χρησιμοποιείται μόνο για εικόνες προϊόντων. Το API του WooCommerce μεταφέρει προϊόντα, απόθεμα, κατηγορίες, μάρκες, πελάτες και παραγγελίες· το API του WordPress είναι αυτό που αναζητά στη Βιβλιοθήκη πολυμέσων και μεταφορτώνει μια εικόνα που δεν υπάρχει ακόμη.',
'Woo_Guide_Wp_App_Password_Note' => 'Χρησιμοποιήστε έναν χρήστη WordPress που μπορεί να διαχειρίζεται πολυμέσα και δημιουργήστε τον κωδικό στο {path}. Αφήστε και τα δύο πεδία κενά και όλα συγχρονίζονται κανονικά — παραλείπεται μόνο η επισύναψη εικόνων.',
'Woo_Guide_Pick_Way_Title' => 'Στη συνέχεια επιλέξτε πώς θα παραμένει συγχρονισμένο',
'Woo_Right_Away' => 'Αμέσως',
'Woo_Stock_Live' => 'απόθεμα σε πραγματικό χρόνο',
'Woo_Stock_Not_Live' => 'απόθεμα όχι σε πραγματικό χρόνο',
'Woo_Guide_Realtime_Lead' => 'Μόνο μία κατεύθυνση: απόθεμα και προϊόντα που φεύγουν από το ERP. Οι παραγγελίες και οι αλλαγές προϊόντων στο WooCommerce εξακολουθούν να φτάνουν σύμφωνα με το πρόγραμμα — δείτε την άλλη καρτέλα.',
'Woo_Push_Stock_On_Change' => 'Αποστολή αποθέματος τη στιγμή που αλλάζει',
'Woo_Setting_People_Miss' => 'Αυτή είναι η ρύθμιση που ξεχνούν οι περισσότεροι',
'Woo_Guide_Pos_Sale_Not_Reach' => 'Μια πώληση POS {not} φτάνει στο WooCommerce από μόνη της. Αν μείνει ανενεργή, το κατάστημα το μαθαίνει μόνο στον επόμενο συγχρονισμό αποθέματος — σε μία ώρα, από προεπιλογή — και σε αυτό το διάστημα μπορεί να πουλήσει μια μονάδα που έχετε ήδη πουλήσει στο ταμείο.',
'Woo_Does_Not' => 'δεν',
'Woo_Guide_Tick_Instant' => 'Επιλέξτε {option} στην καρτέλα {settings}. Αυτή είναι όλη η ρύθμιση — χωρίς worker, χωρίς cron. Κάθε πώληση, επιστροφή, προσαρμογή, μεταφορά και παραληφθείσα αγορά στέλνει τότε μια ενημέρωση μόνο για αυτά τα προϊόντα, αμέσως μετά την αποθήκευση της πώλησης, και μια πώληση είκοσι γραμμών κοστίζει μία αποστολή, όχι είκοσι. Το ταμείο δεν περιμένει ποτέ.',
'Woo_Currently' => 'Τρέχουσα κατάσταση:',
'Woo_Instant_On_Text' => 'ενεργό — το απόθεμα αποστέλλεται σε κάθε αλλαγή',
'Woo_Instant_Off_Text' => 'ανενεργό — το απόθεμα μόνο σύμφωνα με το πρόγραμμα',
'Woo_Guide_Instant_Note' => 'Αποστέλλονται μόνο τα προϊόντα που είναι ήδη συνδεδεμένα με το WooCommerce — ένα προϊόν που δεν έχει συγχρονιστεί ποτέ δεν έχει τίποτα στο κατάστημα για διόρθωση. Τα προϊόντα με παραλλαγές περνούν από το γονικό τους και ένα combo αποστέλλεται ξανά όταν μετακινηθεί οποιοδήποτε από τα στοιχεία του. Οι μαζικές λειτουργίες (διαγραφή προϊόντος, επαναφορά αποθήκης) γράφουν απόθεμα χωρίς να ενεργοποιούν συμβάν, γεγονός που αποτελεί έναν λόγο να διατηρήσετε και τον ωριαίο συγχρονισμό αποθέματος.',
'Woo_Push_Products_On_Save' => 'Αποστολή προϊόντων τη στιγμή που αποθηκεύονται',
'Woo_Guide_Tick_Auto_Products' => 'Επιλέξτε {option} στην καρτέλα {settings} και ένα προϊόν που δημιουργείται, επεξεργάζεται ή αντιγράφεται στο Stocky αποστέλλεται στο WooCommerce αμέσως μετά την αποθήκευσή του — στοιχεία, τιμή, παραλλαγές και εικόνες, και στη συνέχεια το απόθεμά του. Ένα νέο προϊόν δημιουργείται αμέσως στο κατάστημα αντί να περιμένει τον νυχτερινό συγχρονισμό προϊόντων.',
'Woo_On' => 'ενεργό',
'Woo_Off' => 'ανενεργό',
'Woo_Guide_Bulk_Imports_Note' => 'Οι μαζικές εισαγωγές δεν αποστέλλονται μία προς μία — εκτελέστε συγχρονισμό προϊόντων μετά από μια εισαγωγή. Συγχρονίστε πρώτα κατηγορίες και μάρκες, ώστε ένα προϊόν που αποστέλλεται να καταλήξει στη σωστή κατηγορία.',
'Woo_Nothing_Else_To_Install' => 'Τίποτα άλλο για εγκατάσταση',
'Woo_Guide_Same_Process' => 'Χωρίς queue worker, χωρίς καταχώριση cron. Η αποστολή εκτελείται στην ίδια διεργασία που εξυπηρέτησε την πώληση, {after} την αποστολή της απάντησης, οπότε το ταμείο δεν περιμένει ποτέ το WooCommerce. Οι αποστολές δεν επικαλύπτονται ποτέ: οι αλλαγές που γίνονται ενώ εκτελείται μία την περιμένουν και αποστέλλονται αμέσως μετά.',
'Woo_After' => 'μετά',
'Woo_Guide_Shop_Stops_Answering' => 'Ένα κατάστημα που σταματά να απαντά εγκαταλείπεται μετά από οκτώ δευτερόλεπτα και οι αποστολές διακόπτονται για πέντε λεπτά ώστε κάθε πώληση να μην το περιμένει ξανά· οι αλλαγές που ήρθαν στο μεταξύ αποστέλλονται με την πρώτη αποστολή μετά την παύση και ο ωριαίος συγχρονισμός αποθέματος καλύπτει τη διαφορά σε κάθε περίπτωση. Κάθε παύση καταγράφεται στην καρτέλα Αρχεία καταγραφής.',
'Woo_Guide_Artisan_Exception' => 'Μία εξαίρεση: μια αλλαγή αποθέματος από εντολή artisan δεν έχει απάντηση μετά την οποία να εκτελεστεί, οπότε τοποθετείται στην ουρά {queue}. Για να αποστέλλονται κι αυτές άμεσα, αδειάστε αυτή την ουρά:',
'Woo_Cron_Line_Copied' => 'Η γραμμή cron αντιγράφηκε',
'Woo_Command_Copied' => 'Η εντολή αντιγράφηκε',
'Woo_Guide_Not_Woo_Queue' => 'Σκόπιμα όχι η ουρά {queue}: εκείνη μεταφέρει τις παρτίδες καταλόγου πολλών ωρών και μια άμεση αποστολή σε ουρά πίσω από μία τέτοια δεν θα ήταν άμεση.',
'Woo_On_A_Schedule' => 'Με χρονοπρογραμματισμό',
'Woo_Guide_Scheduled_Lead' => 'Όλα ελέγχονται ξανά κατά διαστήματα, και προς τις δύο κατευθύνσεις. Έτσι φτάνουν οι παραγγελίες στο ERP, έτσι δημοσιεύεται ένας κατάλογος και έτσι διορθώνεται ό,τι έχασε η γρήγορη διαδρομή. Κάθε εργασία έχει τη δική της καταχώριση cron, οπότε εκτελείτε μόνο ό,τι θέλετε.',
'Woo_Guide_Sync_Drains_Queue' => 'Η {command} αδειάζει τη δική της ουρά όσο εκτελείται, οπότε αυτές οι γραμμές δεν χρειάζονται ξεχωριστό worker. Στα Windows, χρησιμοποιήστε τον Χρονοπρογραμματιστή εργασιών με πρόγραμμα {program} και τα ίδια ορίσματα, με έναρξη στο {path}.',
'Woo_Or_No_Cron' => 'Ή καθόλου cron',
'Woo_Guide_No_Cron_Text' => 'Κάθε καρτέλα εδώ συγχρονίζει κατ\' απαίτηση και ένας χειροκίνητος συγχρονισμός αδειάζει τις δικές του παρτίδες όσο η σελίδα είναι ανοιχτή — οπότε ένα μικρό κατάστημα μπορεί να λειτουργεί χωρίς καμία καταχώριση cron. Αυτό που χάνετε είναι ό,τι συμβαίνει όταν κανείς δεν κοιτάζει: οι παραγγελίες φτάνουν μόνο όταν κάποιος πατήσει το κουμπί.',
'Woo_Commands_Worth_Knowing' => 'Χρήσιμες εντολές',
'Woo_Worth_Knowing' => 'Καλό να γνωρίζετε',
'Woo_Guide_Changing_Url_Clears' => 'Η αλλαγή του URL του καταστήματος ή των κλειδιών API καθαρίζει κάθε αντιστοίχιση — προϊόντα, κατηγορίες, μάρκες και πελάτες συγχρονίζονται ξανά με το νέο κατάστημα.',
'Woo_Guide_Keep_Skus' => 'Διατηρήστε τα SKU συνεπή μεταξύ Stocky και WooCommerce: αυτό αποτρέπει τα διπλότυπα και κάνει ασφαλή την επανασύνδεση.',
'Woo_Guide_Stock_Total' => 'Το απόθεμα που δημοσιεύεται στο Woo είναι το {total}, όχι ο αριθμός μίας αποθήκης.',
'Woo_Total_Across_Warehouses' => 'σύνολο όλων των αποθηκών',
'Woo_Guide_Full_Reference' => 'Η πλήρης αναφορά — κάθε εύρος, πώς συμπεριφέρεται η ουρά και μια λίστα αντιμετώπισης προβλημάτων — βρίσκεται στο {file}.',
'Woo_Way_Covers' => 'Καλύπτει',
'Woo_Way_Covers_Realtime' => 'Μόνο το απόθεμα που φεύγει από το ERP — μια πώληση POS, μια επιστροφή, μια προσαρμογή, μια παραληφθείσα αγορά',
'Woo_Way_Covers_Scheduled' => 'Τα πάντα, και προς τις δύο κατευθύνσεις: παραγγελίες και αλλαγές προϊόντων προς τα μέσα, κατάλογος και απόθεμα προς τα έξω',
'Woo_Way_Speed' => 'Ταχύτητα',
'Woo_Way_Seconds' => 'Δευτερόλεπτα',
'Woo_Way_Speed_Scheduled' => 'Ό,τι ορίσετε στην καταχώριση cron (απόθεμα ανά ώρα, παραγγελίες κάθε 15 λεπ.)',
'Woo_Way_Needs' => 'Απαιτεί',
'Woo_Way_Needs_Realtime' => 'Τίποτα — μόνο τη ρύθμιση',
'Woo_Way_Needs_Scheduled' => 'Μια καταχώριση cron ανά εργασία — ή τίποτα, αν συγχρονίζετε χειροκίνητα',
'Woo_Way_Switched_On_At' => 'Ενεργοποιείται στο',
'Woo_Way_Cron_Entries_Below' => 'Τις παρακάτω καταχωρίσεις cron',
'Woo_Cron_Orders' => 'Παραγγελίες κάθε 15 λεπτά — μόνο όσες άλλαξαν από την τελευταία εκτέλεση.',
'Woo_Cron_Products_Pull' => 'Αλλαγές προϊόντων από το κατάστημα, κάθε νύχτα στις 03:00.',
'Woo_Cron_Customers' => 'Πελάτες, κάθε νύχτα στις 03:30.',
