'Woo_Cron_Products_Push' => 'Προϊόντα που δεν έχουν συνδεθεί ακόμη, κάθε νύχτα στις 02:00. Τα υπάρχοντα προϊόντα δεν ξαναγράφονται.',
'Woo_Cmd_Stock' => 'Αποστολή αποθέματος για κάθε συνδεδεμένο προϊόν τώρα.',
'Woo_Cmd_Products_Unsynced' => 'Δημοσίευση προϊόντων που δεν έχουν ακόμη WooCommerce id.',
