'Woo_Cmd_Orders_Full' => 'Επανασάρωση κάθε παραγγελίας αντί μόνο των πρόσφατων αλλαγών.',
'Woo_Cmd_Pull' => 'Όλα τα εισερχόμενα μαζί: προϊόντα, παραγγελίες, πελάτες.',
'Woo_Guide_Page_Title' => 'Οδηγός WooCommerce',
'Woo_Guide_Page_Subtitle' => 'Σύνδεση του καταστήματος, τι εκτελείται αυτόματα και οι καταχωρίσεις cron για αυτόν τον διακομιστή',
'Woo_Settings_Button' => 'Ρυθμίσεις WooCommerce',
'Woo_No_Shop_Connected' => 'Δεν έχει συνδεθεί ακόμη κατάστημα',
'Woo_No_Shop_Connected_Desc' => 'Όλα τα παρακάτω εξακολουθούν να ισχύουν — εισαγάγετε το URL του καταστήματος και τα κλειδιά API στη σελίδα ρυθμίσεων WooCommerce και επιστρέψτε.',
'Woo_Wp_Username' => 'Όνομα χρήστη WordPress',
'Woo_Wp_App_Password' => 'Κωδικός εφαρμογής WordPress',
'Woo_Settings_Instant_Hint' => 'Μια πώληση, επιστροφή ή προσαρμογή στέλνει ενημέρωση αποθέματος μόνο για αυτά τα προϊόντα τη στιγμή που αποθηκεύεται, ώστε το κατάστημα να είναι σωστό μέσα σε δευτερόλεπτα αντί στον επόμενο ωριαίο συγχρονισμό αποθέματος. Τίποτα άλλο για εγκατάσταση — η αποστολή εκτελείται αφού απαντηθεί η πώληση, οπότε το ταμείο δεν περιμένει ποτέ το WooCommerce. Περισσότερα στην καρτέλα {guide}.',
'Woo_Settings_Instant_Off_Alert' => 'Αν μείνει ανενεργό, μια πώληση POS φτάνει στο WooCommerce μόνο στον επόμενο συγχρονισμό αποθέματος — έως και μία ώρα αργότερα.',
'Woo_Settings_Auto_Products_Hint' => 'Ένα προϊόν που δημιουργείται, επεξεργάζεται ή αντιγράφεται στο Stocky αποστέλλεται στο WooCommerce αμέσως μετά την αποθήκευσή του — στοιχεία, τιμή, παραλλαγές, εικόνες και στη συνέχεια το απόθεμά του — αντί να περιμένει συγχρονισμό προϊόντων. Οι μαζικές εισαγωγές δεν αποστέλλονται· εκτελέστε συγχρονισμό προϊόντων μετά από μια εισαγωγή.',
'Woo_Sync_Tuning' => 'Ρύθμιση συγχρονισμού',
'Woo_Sync_Tuning_Intro' => 'Οι προεπιλογές ταιριάζουν στα περισσότερα καταστήματα. Αλλάξτε τες μόνο αν ο συγχρονισμός είναι αργός ή λήγει ο χρόνος στη φιλοξενία σας. Κάθε τιμή περιορίζεται σε ασφαλές εύρος και η εκκαθάριση ενός πεδίου επαναφέρει την προεπιλογή του.',
'Woo_Setting_This_Up' => 'Ρύθμιση',
'Woo_Setting_This_Up_Text' => 'Η απόκτηση των κλειδιών API, σε τι χρησιμεύει ο κωδικός εφαρμογής WordPress, οι καταχωρίσεις cron για προγραμματισμένους συγχρονισμούς και πώς να φτάνει το απόθεμα στο κατάστημα τη στιγμή που αλλάζει — όλα αυτά, με τις γραμμές cron αυτού του διακομιστή έτοιμες για αντιγραφή, βρίσκονται στην καρτέλα Οδηγός. Ένα αντίγραφο, ώστε να μην αποκλίνει από αυτό που πραγματικά κάνει η ενότητα.',
