'Telegram_G_A_Channel' => 'Ένα κανάλι',
'Telegram_G_Administrator' => 'διαχειριστή',
'Telegram_G_GetUpdates_Intro' => 'Για ομάδα ή κανάλι, ανοίξτε αυτή τη διεύθυνση σε πρόγραμμα περιήγησης με το δικό σας token και ανανεώστε τη μετά τη δημοσίευση:',
'Telegram_G_Chat_Id_Note' => 'Αναζητήστε το {json}. Το ID ομάδας ή καναλιού είναι αρνητικό, π.χ. {example} — αντιγράψτε το ολόκληρο, μαζί με το σύμβολο μείον.',
'Telegram_G_Step3_Title' => 'Σύνδεση εδώ',
'Telegram_G_Step3_Body' => 'Στην καρτέλα {settings} επικολλήστε το token του bot και το chat ID, επιλέξτε {all} ή μόνο τα συμβάντα που θέλετε {events}, ενεργοποιήστε το {enable} και αποθηκεύστε. Στη συνέχεια πατήστε {test}.',
'Telegram_G_State_Enabled' => 'ενεργό',
'Telegram_G_State_Off' => 'αποθηκευμένο, αλλά απενεργοποιημένο',
'Telegram_G_State_Not_Configured' => 'δεν έχει ρυθμιστεί ακόμη',
'Telegram_G_Chat_Label' => 'συνομιλία {id}',
'Telegram_G_How_Sent' => 'Πώς αποστέλλονται τα μηνύματα',
'Telegram_G_A_Title' => 'Αμέσως — τίποτα για εγκατάσταση',
'Telegram_G_A_Body' => 'Μια πώληση, αγορά, πληρωμή ή έξοδο που αποθηκεύεται στο Stocky — στο POS ή στη διαχείριση — αποστέλλεται στο Telegram {after} την αποθήκευσή του, στο ίδιο αίτημα. Χωρίς καταχώριση cron, χωρίς queue worker, και ο ταμίας δεν περιμένει ποτέ το Telegram: η πώληση έχει ήδη απαντηθεί όταν φεύγει το μήνυμα.',
'Telegram_G_Right_After' => 'αμέσως μετά',
'Telegram_G_B_Title' => 'Η καταχώριση cron — για επαναλήψεις και συμβάντα παρασκηνίου',
'Telegram_G_B_Body' => 'Δύο είδη μηνυμάτων περιμένουν αντί αυτού στη δική τους ουρά Telegram: μια αποστολή που απέτυχε (το Telegram δεν ήταν προσβάσιμο για λίγο), η οποία επαναλαμβάνεται έως τρεις ακόμη φορές τα επόμενα λεπτά· και συμβάντα που προκύπτουν εκτός της διαχείρισης — παραγγελίες που εισάγονται από WooCommerce ή Shopify, εντολές artisan. Αυτή η καταχώριση cron τα αποστέλλει, και τίποτα άλλο:',
'Telegram_G_Cron_Note' => 'Κάθε λεπτό είναι σωστό: μια εκτέλεση χωρίς τίποτα σε αναμονή τερματίζεται αμέσως. Στο cPanel αυτό μπαίνει στο {cronJobs} — χρησιμοποιήστε την πλήρη διαδρομή προς PHP 8.2+ αν το {php} είναι παλαιότερο. Στα Windows, χρησιμοποιήστε τον Χρονοπρογραμματιστή εργασιών με πρόγραμμα {program}, ορίσματα {args}, με έναρξη στο {path}.',
'Telegram_G_Waiting' => '{n} σε αναμονή αποστολής',
'Telegram_G_Nothing_Waiting' => 'τίποτα σε αναμονή',
'Telegram_G_Gave_Up' => '{n} εγκαταλείφθηκαν μετά από επαναλήψεις',
'Telegram_G_Growing_Note' => '— αν αυτός ο αριθμός συνεχίζει να αυξάνεται, η καταχώριση cron δεν εκτελείται.',
'Telegram_G_Without_Cron' => 'Χωρίς την καταχώριση cron, ό,τι αποθηκεύεται στο Stocky εξακολουθεί να φτάνει αμέσως· χάνετε μόνο τις επαναλήψεις και τις εισαγόμενες παραγγελίες.',
'Telegram_G_Everything_Else' => 'Όλα τα άλλα',
