'Salla_Pull_Orders_From' => 'Λήψη παραγγελιών από το {name}',
'Salla_Pull_Orders_Desc' => 'Οι νέες παραγγελίες Salla φτάνουν κανονικά από μόνες τους μέσω webhooks και γίνονται πωλήσεις. Χρησιμοποιήστε αυτή τη λήψη για να συμπληρώσετε παραγγελίες που έγιναν πριν ρυθμιστεί το webhook — οι ήδη εισαγόμενες παραγγελίες παραλείπονται.',
'Salla_Import_Into_Warehouse' => 'Εισαγωγή σε αποθήκη',
'Salla_Default_Warehouse_Option' => 'Προεπιλογή (ρυθμίσεις / πρώτη αποθήκη)',
'Salla_Pull_Orders' => 'Λήψη παραγγελιών',
'Salla_All_Levels' => 'Όλα τα επίπεδα',
'Salla_Error' => 'Σφάλμα',
'Salla_Clear_Logs_Confirm' => 'Εκκαθάριση όλων των αρχείων καταγραφής {name};',
'Salla_Clear_Logs' => 'Εκκαθάριση αρχείων καταγραφής',
'Salla_Guide_1' => 'Δημιουργήστε μια (ιδιωτική) εφαρμογή στο {link} και επιλέξτε τη ροή εξουσιοδότησης {mode}.',
'Salla_Guide_2' => 'Αντιγράψτε το {clientId} και το {clientSecret} της εφαρμογής στην καρτέλα Σύνδεση και αποθηκεύστε.',
'Salla_Guide_3' => 'Στις ρυθμίσεις της εφαρμογής, ορίστε το OAuth callback URL που εμφανίζεται στην καρτέλα Σύνδεση.',
'Salla_Guide_4' => 'Στη σελίδα Webhooks της εφαρμογής: επιλέξτε τη στρατηγική ασφαλείας {signature}, αντιγράψτε το secret της στο πεδίο Webhook Secret εδώ, ορίστε το Webhook URL που εμφανίζεται στην καρτέλα Σύνδεση και εγγραφείτε τουλάχιστον στα {e1}, {e2}, {e3}, {e4}, {e5} και {e6}.',
'Salla_Guide_5' => 'Κάντε κλικ στο {connect} και εγκρίνετε την εφαρμογή στο κατάστημά σας. (Οι εφαρμογές σε Easy Mode συνδέονται αυτόματα μέσω του webhook {webhook}.)',
'Salla_Guide_6' => 'Λάβετε ή αποστείλετε προϊόντα και στη συνέχεια αποστείλετε απόθεμα. Οι νέες παραγγελίες φτάνουν αυτόματα και εμφανίζονται στις Πωλήσεις με αναφορές όπως {ref}.',
'Salla_Identity_Sku_Title' => 'Η ταυτότητα του προϊόντος είναι το SKU',
'Salla_Identity_Sku_Desc' => 'Ο κωδικός προϊόντος του Stocky αντιστοιχίζεται με το SKU του Salla. Διατηρήστε τα SKU συνεπή και στις δύο πλευρές· τα προϊόντα με παραλλαγές αντιστοιχίζονται κατά τη λήψη και στις παραγγελίες, αλλά δεν αποστέλλονται σε αυτή την έκδοση.',
'Salla_Connected_To' => 'Συνδέθηκε με {name}',
'Salla_Connection_Test_Failed' => 'Ο έλεγχος σύνδεσης απέτυχε',
'Salla_Removed_Links' => 'Αφαιρέθηκαν {n} συνδέσεις',
'Salla_Store_Connected' => 'Το κατάστημα Salla συνδέθηκε.',
'Presta_Not_Configured' => 'Δεν έχει ρυθμιστεί',
'Presta_Hero_Desc' => 'Συγχρονισμός προϊόντων, αποθέματος και παραγγελιών με το κατάστημα PrestaShop σας μέσω του webservice API του.',
'Presta_Webservice_Key' => 'Κλειδί webservice',
'Presta_Saved_Paste_New_Key' => 'Αποθηκεύτηκε — επικολλήστε νέο κλειδί για αντικατάσταση',
'Presta_From_Menu' => 'Από {menu}',
'Presta_Webservice_Key_Help' => 'Ενεργοποιήστε το webservice στο PrestaShop ({menu}), δημιουργήστε ένα κλειδί με δικαιώματα σε products, stock_availables, orders και customers και επικολλήστε το εδώ. Αποθηκεύεται μόνο για εγγραφή.',
'Presta_Shop_Language_Id' => 'ID γλώσσας καταστήματος',
'Presta_Shop_Language_Help' => 'Το id γλώσσας που χρησιμοποιείται για τα ονόματα προϊόντων κατά την αποστολή (1 = η πρώτη γλώσσα του καταστήματος).',
'Presta_Push_Products_Desc' => 'Δημιουργεί τα απλά προϊόντα που λείπουν στο PrestaShop (με το τρέχον απόθεμά τους). Τα ήδη συνδεδεμένα προϊόντα και τα προϊόντα με παραλλαγές παραλείπονται — συνεχίστε να επεξεργάζεστε τα στοιχεία προϊόντων στο PrestaShop ή κάντε λήψη για ανανέωση του τοπικού αντιγράφου.',
'Presta_Pull_Products_Desc' => 'Εισάγει προϊόντα PrestaShop, αντιστοιχίζοντας τα υπάρχοντα βάσει reference (SKU) και δημιουργώντας τα υπόλοιπα. Οι συνδυασμοί εισάγονται ως το γονικό τους προϊόν.',
'Presta_Reset_Product_Confirm' => 'Επαναφορά συνδέσεων προϊόντων; Το ιστορικό παραγγελιών διατηρεί τις συνδέσεις του.',
'Presta_Push_Stock_Desc' => 'Ενημερώνει το απόθεμα του καταστήματος (stock_availables) για κάθε συνδεδεμένο προϊόν.',
'Presta_Pull_Orders_Desc' => 'Εισάγει τις παραγγελίες του καταστήματος ως πωλήσεις (αναφορές όπως {ref}), ξεκινώντας από τις νεότερες. Οι ήδη εισαγόμενες και ακυρωμένες παραγγελίες παραλείπονται, οπότε η τακτική λήψη είναι ασφαλής. Το PrestaShop δεν έχει webhooks — εκτελέστε το μετά από περιόδους αυξημένης κίνησης.',
'Presta_Guide_1' => 'Στο back office του PrestaShop, ανοίξτε το {menu} και ενεργοποιήστε το webservice.',
'Presta_Guide_2' => 'Προσθέστε νέο κλειδί, παρέχοντας {rw} σε {products} και {stock}, και {view} σε {orders} και {customers}.',
'Presta_Guide_3' => 'Επικολλήστε το URL του καταστήματος και το κλειδί στην καρτέλα Σύνδεση, αποθηκεύστε και εκτελέστε {test}.',
'Presta_Guide_4' => 'Κάντε πρώτα λήψη προϊόντων αν το κατάστημα έχει ήδη κατάλογο (αντιστοίχιση βάσει reference/SKU)· κάντε αποστολή για να δημιουργηθούν τα απλά προϊόντα που λείπουν.',
'Presta_Guide_5' => 'Αποστέλλετε απόθεμα όποτε αλλάζουν οι ποσότητες και λαμβάνετε παραγγελίες τακτικά — το PrestaShop δεν έχει webhooks, οπότε οι παραγγελίες φτάνουν μόνο όταν κάνετε λήψη.',
'Presta_Identity_Title' => 'Η ταυτότητα του προϊόντος είναι το reference (SKU)',
'Presta_Identity_Desc' => 'Ο κωδικός προϊόντος του Stocky αντιστοιχίζεται με το reference του PrestaShop. Διατηρήστε τα references συνεπή και στις δύο πλευρές· οι συνδυασμοί (παραλλαγές) αντιστοιχίζονται στις παραγγελίες βάσει reference αλλά δεν αποστέλλονται σε αυτή την έκδοση.',
'Xero_Hero_Title' => 'Συγχρονισμός λογιστικής Xero',
'Xero_Hero_Desc' => 'Αποστολή των πελατών σας ως επαφών Xero και των πωλήσεών σας ως τιμολογίων — με πληρωμές όταν έχει ρυθμιστεί τραπεζικός λογαριασμός.',
'Xero_App_Credentials_Accounts' => 'Διαπιστευτήρια εφαρμογής & λογαριασμοί',
'Xero_From_Dev_App' => 'Από την εφαρμογή σας στο developer.xero.com',
'Xero_Sales_Account_Code' => 'Κωδικός λογαριασμού πωλήσεων',
'Xero_Sales_Account_Help' => 'Λογαριασμός εσόδων για τις γραμμές τιμολογίου (το \'200\' είναι ο προεπιλεγμένος λογαριασμός Sales του Xero).',
'Xero_Payment_Account_Code' => 'Κωδικός λογαριασμού πληρωμών (προαιρετικό)',
'Xero_Payment_Account_Ph' => 'π.χ. 090',
'Xero_Payment_Account_Help' => 'Ένας κωδικός τραπεζικού λογαριασμού. Όταν οριστεί, οι εξοφλημένες πωλήσεις καταγράφουν επίσης πληρωμή στο τιμολόγιο· αφήστε κενό για συγχρονισμό μόνο τιμολογίων.',
'Xero_Auto_Sync_Sales' => 'Αυτόματος συγχρονισμός νέων πωλήσεων ως τιμολογίων',
'Xero_Auto_Sync_Sales_Hint' => '(σε ουρά στο παρασκήνιο καθώς δημιουργούνται οι πωλήσεις)',
'Xero_Org_Connection' => 'Σύνδεση οργανισμού',
'Xero_Organisation' => 'Οργανισμός',
'Xero_Disconnect_Confirm' => 'Αποσύνδεση του οργανισμού Xero; Ο συγχρονισμός σταματά μέχρι να συνδεθείτε ξανά.',
'Xero_Redirect_Uri_Title' => 'Redirect URI για την εφαρμογή Xero',
'Xero_Redirect_Uri_Help' => 'Δημιουργήστε μια «Web app» στο {link} και καταχωρίστε αυτό το redirect URI. Σημείωση: τα access tokens του Xero ανανεώνονται αυτόματα, αλλά μια σύνδεση αδρανής για πάνω από 60 ημέρες πρέπει να συνδεθεί ξανά.',
'Xero_Total_Customers' => 'Σύνολο πελατών',
'Xero_Contacts_In_Xero' => 'Επαφές στο Xero',
'Xero_Total_Sales' => 'Σύνολο πωλήσεων',
'Xero_Invoices_In_Xero' => 'Τιμολόγια στο Xero',
'Xero_Payments_Recorded' => 'Καταγεγραμμένες πληρωμές',
'Xero_Push_Customers_To' => 'Αποστολή πελατών στο {name}',
'Xero_Push_Customers_Desc' => 'Δημιουργεί ή ενημερώνει μια επαφή Xero για κάθε πελάτη. Ένας πελάτης του οποίου το όνομα υπάρχει ήδη στο Xero συνδέεται με εκείνη την επαφή.',
'Xero_Push_Customers' => 'Αποστολή πελατών',
'Xero_Push_Sales_Invoices' => 'Αποστολή πωλήσεων ως τιμολογίων',
'Xero_Push_Invoices_Desc' => 'Δημιουργεί ένα τιμολόγιο AUTHORISED ανά πώληση (αριθμός τιμολογίου = η Αναφορά της πώλησης), με τα είδη της πώλησης και γραμμές μεταφορικών, έκπτωσης και φόρου ώστε το σύνολο στο Xero να ταιριάζει με το σύνολο της πώλησης. Οι πωλήσεις που υπάρχουν ήδη στο Xero παραλείπονται — τα τιμολόγια δεν τροποποιούνται ποτέ. Οι επαφές που λείπουν δημιουργούνται επιτόπου.',
'Xero_Push_Invoices' => 'Αποστολή τιμολογίων',
'Xero_Reset_Contact_Confirm' => 'Επαναφορά συνδέσεων επαφών; Η επόμενη αποστολή θα τις συνδέσει ξανά ή θα τις αναδημιουργήσει.',
'Xero_Reset_Contact_Links' => 'Επαναφορά συνδέσεων επαφών',
'Xero_Guide_1' => 'Δημιουργήστε μια {webApp} στο {link} ({menu}).',
'Xero_Guide_2' => 'Καταχωρίστε το redirect URI που εμφανίζεται στην καρτέλα Σύνδεση.',
'Xero_Guide_3' => 'Αντιγράψτε το {clientId} της εφαρμογής και δημιουργήστε ένα {clientSecret}· επικολλήστε και τα δύο εδώ και αποθηκεύστε.',
'Xero_Guide_4' => 'Κάντε κλικ στο {connect}, συνδεθείτε και επιλέξτε τον οργανισμό προς σύνδεση.',
'Xero_Guide_5' => 'Ελέγξτε τους κωδικούς λογαριασμών: ο λογαριασμός πωλήσεων λαμβάνει τις γραμμές τιμολογίου· ορίστε κωδικό τραπεζικού λογαριασμού αν οι εξοφλημένες πωλήσεις πρέπει να καταγράφουν και πληρωμές.',
'Xero_Guide_6' => 'Αποστείλετε πρώτα τους πελάτες και μετά τα τιμολόγια. Οι αριθμοί τιμολογίων είναι οι Αναφορές των πωλήσεων, οπότε τα διπλότυπα απορρίπτονται από το Xero ακόμη κι αν γίνει επαναφορά των συνδέσεων.',
'Xero_Amounts_Title' => 'Τα ποσά αποστέλλονται με φόρο όπως είναι',
'Xero_Amounts_Desc' => 'Τα τιμολόγια χρησιμοποιούν γραμμές NoTax που αντικατοπτρίζουν ακριβώς την πώληση (είδη + μεταφορικά − έκπτωση + φόρος), ώστε τα σύνολα του Xero να είναι πάντα ίσα με τα σύνολα του Stocky. Ο λογιστής σας μπορεί να αντιστοιχίσει εκ νέου τις γραμμές φόρου και μεταφορικών στους κατάλληλους λογαριασμούς μέσα στο Xero.',
'Xero_Org_Connected' => 'Ο οργανισμός Xero συνδέθηκε.',
'Jumia_Hero_Title' => 'Συγχρονισμός αγοράς Jumia',
'Jumia_Hero_Desc' => 'Αποστολή τιμών και αποθέματος στις καταχωρίσεις σας στο Jumia Seller Center και εισαγωγή παραγγελιών της αγοράς ως πωλήσεων.',
'Jumia_Api_Url_Label' => 'API URL (το endpoint του Seller Center της χώρας σας)',
'Jumia_Account_Email' => 'Email λογαριασμού (User ID)',
'Jumia_Api_Key' => 'Κλειδί API',
'Jumia_Prices_Stock' => 'Τιμές & Απόθεμα',
'Jumia_Push_Prices_Stock_Title' => 'Αποστολή τιμών & αποθέματος στο Jumia',
'Jumia_Push_Prices_Stock_Desc' => 'Στέλνει την τρέχουσα τιμή και ποσότητα για κάθε προϊόν (και παραλλαγή) που έχει SKU που ταιριάζει με το {sku} της καταχώρισης Jumia. Οι ενημερώσεις υποβάλλονται ως feeds του Seller Center και εφαρμόζονται ασύγχρονα — το ID του feed καταγράφεται στην καρτέλα Αρχεία καταγραφής και οι απορρίψεις ανά είδος εμφανίζονται στην οθόνη κατάστασης feed του Seller Center.',
'Jumia_Push_Prices_Stock' => 'Αποστολή τιμών & αποθέματος',
'Jumia_Pull_Orders_Desc' => 'Εισάγει τις παραγγελίες της αγοράς ως πωλήσεις (αναφορές όπως {ref}), αντιστοιχισμένες με τα προϊόντα σας βάσει Seller SKU. Οι ήδη εισαγόμενες και ακυρωμένες παραγγελίες παραλείπονται, οπότε η τακτική λήψη είναι ασφαλής. Οι πληρωμές σημειώνονται ως εξοφλημένες μόνο για παραδομένες παραγγελίες (στο Jumia κυριαρχεί η αντικαταβολή).',
'Jumia_Guide_1' => 'Στο {sellerCenter} του Jumia, ανοίξτε το {menu} και δημιουργήστε κλειδί API.',
'Jumia_Guide_2' => 'Εισαγάγετε το API URL της χώρας σας (π.χ. {ng} για Νιγηρία, {ke} για Κένυα, {eg} για Αίγυπτο), το email του λογαριασμού σας στο Seller Center και το κλειδί — και στη συνέχεια εκτελέστε {test}.',
'Jumia_Guide_3' => 'Βεβαιωθείτε ότι το {sku} κάθε καταχώρισης Jumia είναι ίσο με τον κωδικό προϊόντος του Stocky — αυτή είναι η ταυτότητα που χρησιμοποιείται τόσο για τις αποστολές αποθέματος όσο και για την αντιστοίχιση παραγγελιών.',
'Jumia_Guide_4' => 'Αποστέλλετε τιμές & απόθεμα μετά από αλλαγές αποθέματος· λαμβάνετε παραγγελίες τακτικά (το Jumia δεν έχει webhooks σε αυτό το API).',
'Jumia_Guide_5' => 'Η δημιουργία νέων καταχωρίσεων παραμένει στο Seller Center — το Jumia απαιτεί χαρακτηριστικά ανά κατηγορία και έλεγχο εικόνων που μόνο η πύλη του χειρίζεται σωστά.',
'Mailchimp_Hero_Title' => 'Συγχρονισμός κοινού Mailchimp',
'Mailchimp_Hero_Desc' => 'Διατηρήστε ένα κοινό Mailchimp γεμάτο με τους πελάτες σας, ώστε να μπορείτε να τρέχετε καμπάνιες email στην πραγματική πελατειακή σας βάση.',
'Mailchimp_Account_Audience' => 'Λογαριασμός & κοινό',
'Mailchimp_Api_Key_Ph' => 'π.χ. {example} ({menu})',
'Mailchimp_Audience_Option' => '{name} ({n} μέλη)',
'Mailchimp_Load_Audiences_Ph' => 'Φορτώστε τα κοινά για να επιλέξετε ένα',
'Mailchimp_Load_Audiences' => 'Φόρτωση κοινών',
'Mailchimp_Double_Optin_Label' => 'Διπλή επιβεβαίωση εγγραφής — τα νέα μέλη λαμβάνουν email επιβεβαίωσης πριν προστεθούν',
'Mailchimp_Double_Optin_Hint' => '(συνιστάται για GDPR)',
'Mailchimp_Auto_Sync_Customers' => 'Αυτόματος συγχρονισμός νέων πελατών καθώς δημιουργούνται',
'Mailchimp_With_Email' => 'Με email',
'Mailchimp_Push_Desc' => 'Προσθέτει ή ενημερώνει κάθε πελάτη που έχει διεύθυνση email στο επιλεγμένο κοινό (μαζί με όνομα και τηλέφωνο). Τα υπάρχοντα μέλη διατηρούν την κατάσταση συνδρομής τους — κανείς που απεγγράφηκε δεν εγγράφεται ξανά. Οι πελάτες χωρίς email εξαιρούνται.',
'Mailchimp_Double_Optin_Off_Title' => 'Η διπλή επιβεβαίωση εγγραφής είναι ανενεργή',
'Mailchimp_Double_Optin_Off_Desc' => 'Τα νέα μέλη θα προστίθενται ως εγγεγραμμένα χωρίς email επιβεβαίωσης. Κάντε το μόνο για πελάτες που έχουν ήδη συμφωνήσει να λαμβάνουν μάρκετινγκ.',
'Mailchimp_Guide_1' => 'Στο Mailchimp, ανοίξτε το {menu} και δημιουργήστε ένα κλειδί (τελειώνει σε {suffix} — αυτό το επίθημα είναι το datacenter σας).',
'Mailchimp_Guide_2' => 'Επικολλήστε το κλειδί εδώ, αποθηκεύστε, κάντε κλικ στο {load} και επιλέξτε το κοινό προς συμπλήρωση.',
'Mailchimp_Guide_3' => 'Αφήστε ενεργή τη {doubleOptIn} εκτός αν οι πελάτες σας έχουν ήδη συναινέσει σε email μάρκετινγκ.',
'Mailchimp_Double_Optin_Term' => 'διπλή επιβεβαίωση εγγραφής',
'Mailchimp_Guide_4' => 'Εκτελέστε {push} για την αρχική συμπλήρωση· ενεργοποιήστε τον {autoSync} ώστε οι νέοι πελάτες να προστίθενται αυτόματα.',
'Mailchimp_Auto_Sync_Term' => 'αυτόματο συγχρονισμό',
'Mailchimp_Consent_Title' => 'Η συγκατάθεση έχει σημασία',
'Mailchimp_Consent_Desc' => 'Η αποστολή email σε άτομα που δεν συμφώνησαν ποτέ σε μάρκετινγκ μπορεί να παραβιάζει τον GDPR/CAN-SPAM και να οδηγήσει σε αναστολή του λογαριασμού σας στο Mailchimp. Η διπλή επιβεβαίωση εγγραφής μεταφέρει την επιβεβαίωση στο Mailchimp — η ασφαλής προεπιλογή.',
'Mailchimp_No_Audiences' => 'Δεν βρέθηκαν κοινά σε αυτόν τον λογαριασμό.',
'GSheets_Hero_Title' => 'Εξαγωγές Google Sheets',
'GSheets_Hero_Desc' => 'Εξαγάγετε τις πωλήσεις, τα προϊόντα και τους πελάτες σας σε ζωντανό υπολογιστικό φύλλο Google — μία καρτέλα για το καθένα, με ανανέωση κατ\' απαίτηση.',
'GSheets_OAuth_Credentials' => 'Διαπιστευτήρια Google OAuth',
'GSheets_Client_Secret_Ph' => 'Από τον OAuth client σας στο Google Cloud',
'GSheets_Auto_Export' => 'Αυτόματη εξαγωγή κάθε νύχτα',
'GSheets_Auto_Export_Hint' => '(όλες οι καρτέλες ανανεώνονται γύρω στις 02:30 ώρα διακομιστή)',
'GSheets_Enable' => 'Ενεργοποίηση εξαγωγών Google Sheets',
'GSheets_Account_Spreadsheet' => 'Λογαριασμός & υπολογιστικό φύλλο',
'GSheets_Reconnect_Account' => 'Επανασύνδεση λογαριασμού Google',
'GSheets_Connect_Account' => 'Σύνδεση λογαριασμού Google',
'GSheets_Disconnect_Confirm' => 'Αποσύνδεση του λογαριασμού Google; Οι εξαγωγές σταματούν μέχρι να συνδεθείτε ξανά.',
'GSheets_Target_Spreadsheet' => 'Υπολογιστικό φύλλο προορισμού (ID ή πλήρες URL)',
'GSheets_Spreadsheet_Ph' => 'Επικολλήστε το URL ενός υπολογιστικού φύλλου ή δημιουργήστε ένα →',
'GSheets_Create_New' => 'Δημιουργία νέου',
