'Shopify_Create_Missing_Products' => 'Δημιουργία προϊόντων ERP για προϊόντα Shopify που δεν ταιριάζουν με SKU',
'Shopify_Create_Missing_Customers' => 'Δημιουργία πελατών ERP για πελάτες Shopify που δεν ταιριάζουν με email',
'Shopify_Unknown_Customer_Hint' => 'Με αυτό ανενεργό, μια παραγγελία από άγνωστο πελάτη παραλείπεται αντί να γίνει εικασία.',
'Shopify_Entities_Lead' => 'Μόνο οι οντότητες που είναι ενεργές εδώ μπορούν να συγχρονιστούν — ένα κατάστημα από το οποίο απλώς λαμβάνετε παραγγελίες δεν πρέπει να δέχεται μια τυχαία αποστολή προϊόντων που ξαναγράφει τον κατάλογό του.',
'Shopify_Auto_Schedule' => 'Αυτόματος συγχρονισμός με χρονοπρογραμματισμό',
'Shopify_Auto_Schedule_Hint' => 'Απαιτεί καταχώριση cron στον διακομιστή που εκτελεί {cmd} (κάθε 5 λεπτά είναι η μικρότερη συχνότητα που μπορούν να χρησιμοποιήσουν τα παρακάτω διαστήματα). Οι συγχρονισμοί μπορούν πάντα να ξεκινούν χειροκίνητα.',
'Shopify_Push_Stock_On_Change' => 'Αποστολή αποθέματος τη στιγμή που αλλάζει',
'Shopify_Push_Stock_Hint' => 'Μια πώληση, επιστροφή ή προσαρμογή στέλνει ενημέρωση αποθέματος μόνο για αυτά τα προϊόντα τη στιγμή που αποθηκεύεται, ώστε το κατάστημα να είναι σωστό μέσα σε δευτερόλεπτα αντί στην επόμενη προγραμματισμένη εκτέλεση. Τίποτα άλλο για εγκατάσταση — η αποστολή εκτελείται αφού απαντηθεί η πώληση, οπότε το ταμείο δεν περιμένει ποτέ το Shopify.',
'Shopify_Switch_Inventory_First' => 'Ενεργοποιήστε πρώτα το Απόθεμα στην καρτέλα {tab}.',
'Shopify_Leave_Off_Lag' => 'Αν μείνει ανενεργό, μια πώληση POS φτάνει στο Shopify μόνο στην επόμενη αποστολή αποθέματος — έως και {n} λεπτά αργότερα.',
'Shopify_Default_Interval' => 'Προεπιλεγμένο διάστημα (λεπτά)',
'Shopify_Default_Interval_Hint' => 'Χρησιμοποιείται από κάθε βήμα που δεν ορίζει δικό του.',
'Shopify_What_Runs_Auto' => 'Τι εκτελείται αυτόματα',
'Shopify_Step_Hint' => 'Κάθε βήμα είναι μία οντότητα σε μία κατεύθυνση. Οι παραγγελίες έρχονται πάντα μόνο {from} το Shopify.',
'Shopify_From' => 'από',
'Shopify_Add_Step' => 'Προσθήκη βήματος',
'Shopify_Using_Default_Plan' => 'Χρήση του προεπιλεγμένου πλάνου',
'Shopify_Default_Plan_Desc' => 'Οι παραγγελίες λαμβάνονται και το απόθεμα αποστέλλεται κάθε {n} λεπτά. Προσθέστε ένα βήμα για να επιλέξετε το δικό σας — η εκκαθάριση της λίστας επαναφέρει αυτή την προεπιλογή.',
'Shopify_Step_Entity_Off' => 'Το {entity} είναι απενεργοποιημένο στην προηγούμενη καρτέλα — αυτό το βήμα θα παραλειφθεί.',
