'Shopify_Auto_Off_Note' => 'Απενεργοποιημένο — αυτά τα βήματα εκτελούνται μόνο όταν κάποιος πατήσει Συγχρονισμός.',
'Shopify_Auto_On_Note' => 'Ελέγχεται από μια καταχώριση cron που εκτελεί {cmd} — χωρίς αυτήν, τίποτα εδώ δεν εκτελείται μόνο του. Ένας χειροκίνητος συγχρονισμός μετράει ως εκτέλεση: μεταθέτει την επόμενη κατά το διάστημα του βήματος.',
'Shopify_Stock_Lag_Title' => 'Το απόθεμα φτάνει στο Shopify μόνο όταν εκτελείται το βήμα αποστολής αποθέματος',
'Shopify_Stock_Lag_Desc' => 'Μια πώληση στο ταμείο παραμένει αόρατη στο κατάστημα μέχρι τότε — έως και {n} λεπτά, οπότε η τελευταία μονάδα μπορεί ακόμη να πωληθεί δύο φορές online. Ενεργοποιήστε το {setting} και κάθε πώληση, επιστροφή και προσαρμογή αποστέλλεται μέσα σε δευτερόλεπτα.',
'Shopify_Turn_It_On' => 'Ενεργοποίηση',
'Shopify_Stock_Also_Pushed' => 'Το απόθεμα αποστέλλεται επίσης μέσα σε δευτερόλεπτα από κάθε πώληση, επιστροφή ή προσαρμογή, χωρίς να περιμένει κάποιο από τα παραπάνω βήματα.',
'Shopify_Sync_History' => 'Ιστορικό συγχρονισμού',
'Shopify_Nothing_Run_Store' => 'Δεν έχει εκτελεστεί τίποτα για αυτό το κατάστημα',
'Shopify_Hook_Msg_Client' => 'Κάντε κλικ στο «Καταχώριση webhooks» παρακάτω — δεν χρειάζεται να εισαγάγετε τίποτα στο Shopify.',
'Shopify_Hook_Msg_Token' => 'Κάντε κλικ στο «Καταχώριση webhooks» παρακάτω και επικολλήστε το API secret key της εφαρμογής στις ρυθμίσεις του καταστήματος ως μυστικό υπογραφής.',
'Shopify_Hook_Note_Register' => 'Η καταχώριση δημιουργεί τις συνδρομές στο Shopify και τις κατευθύνει αυτόματα σε αυτή τη διεύθυνση. Μην την προσθέσετε χειροκίνητα στο Shopify → Settings → Notifications → Webhooks: εκείνες υπογράφονται με διαφορετικό secret και κάθε παράδοση θα απορριπτόταν.',
'Shopify_Hook_Verified_Client' => 'Οι παραδόσεις επαληθεύονται με το client secret της εφαρμογής, το οποίο είναι ήδη αποθηκευμένο.',
'Shopify_Hook_Signature_Required' => 'Οι παραδόσεις χωρίς έγκυρη υπογραφή απορρίπτονται, οπότε το secret πρέπει να οριστεί πριν τα webhooks κάνουν οτιδήποτε.',
'Shopify_Hook_Retries' => 'Το Shopify επαναλαμβάνει μέχρι να λάβει 2xx και κάθε παράδοση καταγράφεται μία φορά — ένα επαναλαμβανόμενο συμβάν δεν έχει αποτέλεσμα, δεν δημιουργεί διπλότυπη παραγγελία.',
'Shopify_No_Signing_Secret' => 'Δεν υπάρχει αποθηκευμένο μυστικό υπογραφής',
'Shopify_No_Signing_Secret_Desc' => 'Οι συνδρομές μπορούν να δημιουργηθούν χωρίς αυτό, αλλά κάθε παράδοση θα απορρίπτεται μέχρι να αποθηκευτεί το API secret key της εφαρμογής σε αυτό το κατάστημα (το client secret μιας εφαρμογής Dev Dashboard το καλύπτει ήδη).',
'Shopify_Register_In_Shopify' => 'Καταχώριση στο Shopify',
'Shopify_Refresh_List' => 'Ανανέωση λίστας',
'Shopify_Prune_Confirm' => 'Αφαίρεση των συνδρομών μας για οντότητες που αυτό το κατάστημα δεν συγχρονίζει πλέον;',
'Shopify_Tidy_Up' => 'Τακτοποίηση',
'Shopify_Topics_Subscribed' => '{mine} από {total} θέματα με συνδρομή',
'Shopify_Topics_Handled' => 'Θέματα που χειρίζεται αυτό το ERP:',
