'Shopify_Topic_Hint_Refresh' => 'Πατήστε «Ανανέωση λίστας» για να δείτε αν αυτό το κατάστημα έχει συνδρομή',
'Shopify_Topic_Not_Needed' => 'Δεν χρειάζεται — η οντότητά του είναι απενεργοποιημένη για αυτό το κατάστημα',
