'Shopify_Could_Not_Read_Hooks' => 'Δεν ήταν δυνατή η ανάγνωση των webhooks αυτού του καταστήματος',
'Shopify_Hooks_Partial' => '{created} δημιουργήθηκαν, {failed} απέτυχαν — δείτε τα αρχεία καταγραφής',
'Shopify_Subs_Created' => 'Δημιουργήθηκαν {n} συνδρομή(-ές)',
'Shopify_Subs_Created_Removed' => 'Δημιουργήθηκαν {n} συνδρομή(-ές), αφαιρέθηκαν {removed}',
'Shopify_Already_Subscribed' => 'Υπάρχει ήδη συνδρομή σε όλα όσα χρειάζεται αυτό το κατάστημα',
'Shopify_Could_Not_Register' => 'Δεν ήταν δυνατή η καταχώριση των webhooks',
'Shopify_Sub_Removed' => 'Η συνδρομή αφαιρέθηκε',
'Shopify_Could_Not_Remove_Sub' => 'Δεν ήταν δυνατή η αφαίρεση αυτής της συνδρομής',
'Shopify_Could_Not_Load_Store' => 'Δεν ήταν δυνατή η φόρτωση αυτού του καταστήματος',
'Shopify_G_Lead_Store' => 'Τι χρειάζεται αυτό το κατάστημα για να παραμένει συγχρονισμένο. Όλα εδώ αφορούν συγκεκριμένα αυτό το κατάστημα — οι διαδρομές και τα ids είναι πραγματικά, οπότε οι εντολές μπορούν να αντιγραφούν απευθείας στον διακομιστή.',
'Shopify_G_Lead_Generic' => 'Πώς ένα κατάστημα Shopify παραμένει συγχρονισμένο με το ERP. Επιλέξτε ένα κατάστημα παραπάνω για να δείτε την κατάστασή του ή διαβάστε το όπως είναι — η γραμμή cron και το webhook URL είναι ίδια όποιο κατάστημα κι αν συνδέσετε.',
'Shopify_G_Ways_Note' => 'Τα περισσότερα καταστήματα χρησιμοποιούν και τα δύο: το πρώτο κρατά το κατάστημα ενημερωμένο λεπτό προς λεπτό, το δεύτερο πιάνει ό,τι έχασε το πρώτο — ένα webhook που δεν έφτασε ποτέ, μια αλλαγή που έγινε απευθείας στη διαχείριση Shopify, μια νύχτα που ο ιστότοπος ήταν εκτός λειτουργίας.',
'Shopify_G_Both_Need' => 'Και οι δύο κατευθύνσεις χρειάζονται πρώτα αυτό',
'Shopify_G_Credentials' => 'Διαπιστευτήρια Shopify',
'Shopify_G_Cred_Intro' => 'Από τον Ιανουάριο του 2026 το Shopify δεν δημιουργεί πλέον προσαρμοσμένες εφαρμογές μέσα στη διαχείριση, οπότε υπάρχουν δύο είδη σύνδεσης:',
'Shopify_G_Cred_DevDash' => '{app} (κάθε κατάστημα που συνδέεται τώρα) — {path}. Παραχωρήστε τα Admin API scopes για όσα συγχρονίζει αυτό το κατάστημα, εγκαταστήστε την εφαρμογή στο κατάστημα και στη συνέχεια αντιγράψτε το {clientId} και το {clientSecret} από τη σελίδα Settings της εφαρμογής στο {where}. Το ERP τα ανταλλάσσει μόνο του με access token και το ανανεώνει πριν λήξει κάθε 24 ώρες. Το client secret υπογράφει επίσης τα webhooks, οπότε δεν χρειάζεται τίποτα άλλο. Η εφαρμογή και το κατάστημα πρέπει να βρίσκονται στον ίδιο οργανισμό Shopify.',
'Shopify_G_Dev_Dashboard_App' => 'Εφαρμογή Dev Dashboard',
'Shopify_G_Cred_Legacy' => '{app} (δημιουργήθηκε στη διαχείριση πριν από το 2026) — συνεχίζει να λειτουργεί αμετάβλητη με το {token} ({prefix}) και το {secret} ως μυστικό υπογραφής webhook. Δεν είναι η ίδια τιμή με το token, και η εναλλαγή τους είναι ο συνηθέστερος λόγος απόρριψης των webhooks.',
'Shopify_G_Legacy_App' => 'Παλαιού τύπου προσαρμοσμένη εφαρμογή',
'Shopify_G_API_Secret_Key' => 'API secret key',
'Shopify_G_Stored' => 'αποθηκευμένο',
'Shopify_G_Missing_Refused' => 'λείπει — οι παραδόσεις θα απορρίπτονται',
'Shopify_G_Where_Data_Desc' => '{path} Η αποθήκη ERP της οποίας το απόθεμα πουλά αυτό το κατάστημα και η τοποθεσία Shopify στην οποία γράφεται αυτό το απόθεμα. Ο συγχρονισμός αποθέματος και η εισαγωγή παραγγελιών αρνούνται να εκτελεστούν χωρίς αυτά.',
'Shopify_G_Currently' => 'Τρέχουσα κατάσταση: αποθήκη {warehouse}, τοποθεσία {location}',
'Shopify_G_Not_Set_Lower' => 'δεν έχει οριστεί',
'Shopify_G_Ready' => 'έτοιμο',
'Shopify_G_Incomplete' => 'ελλιπές',
'Shopify_G_Manual_Syncs' => 'Συγχρονισμοί που ξεκινάτε χειροκίνητα',
'Shopify_G_Manual_Desc' => 'Ένας συγχρονισμός που ξεκινά από το {centre} απαντά αμέσως και εκτελείται στο παρασκήνιο, σε σύντομα τμήματα που το καθένα συνεχίζει από εκεί που σταμάτησε το προηγούμενο. Ένας μεγάλος κατάλογος δεν διακόπτεται ποτέ στη μέση από φιλοξενία που τερματίζει μεγάλα αιτήματα web (LiteSpeed, nginx, load balancer), και το κλείσιμο της σελίδας δεν τον σταματά. Ο worker για αυτό είναι μία ακόμη γραμμή cron:',
'Shopify_G_Cron_Copied' => 'Η γραμμή cron αντιγράφηκε',
'Shopify_G_Manual_Note' => 'Χωρίς αυτόν, ένας συγχρονισμός εξακολουθεί να ολοκληρώνεται, αλλά μόνο όσο η σελίδα Κέντρο συγχρονισμού παραμένει ανοιχτή: όταν κανένας worker δεν αναλαμβάνει μια εκτέλεση μέσα σε λίγα δευτερόλεπτα, η σελίδα τη συνεχίζει η ίδια, ένα σύντομο αίτημα τη φορά. Στα Windows χρησιμοποιήστε τον Χρονοπρογραμματιστή εργασιών κάθε λεπτό: πρόγραμμα {program}, ορίσματα {args}, με έναρξη στο {dir}.',
'Shopify_G_Then_Pick' => 'Στη συνέχεια επιλέξτε πώς θα παραμένει συγχρονισμένο',
'Shopify_G_Right_Away' => 'Αμέσως',
'Shopify_G_Stock_Live' => 'απόθεμα σε πραγματικό χρόνο',
'Shopify_G_Stock_Not_Live' => 'απόθεμα όχι σε πραγματικό χρόνο',
'Shopify_G_Realtime_Lead' => 'Κάθε αλλαγή αποστέλλεται τη στιγμή που συμβαίνει, σε δευτερόλεπτα. Δύο μισά, με ξεχωριστούς διακόπτες: τα {webhooks} φέρνουν τα συμβάντα του καταστήματος προς τα μέσα και η {push} στέλνει το απόθεμα προς τα έξω.',
'Shopify_G_Webhooks_Lower' => 'webhooks',
'Shopify_G_Instant_Push_Lower' => 'άμεση αποστολή αποθέματος',
'Shopify_G_Webhooks_In' => 'Webhooks — το κατάστημα → το ERP',
'Shopify_G_Webhooks_Desc' => 'Παραγγελίες, αλλαγές κατάστασης παραγγελιών και αλλαγές προϊόντων, πελατών και αποθέματος που γίνονται στο Shopify. Ανοίξτε το κατάστημα και πατήστε {button} στην {tab} του — είναι ασφαλές να το πατήσετε δύο φορές. Το Shopify στέλνει στο:',
'Shopify_G_Webhooks_Tab' => 'καρτέλα Webhooks',
'Shopify_G_Webhooks_Note' => 'Η διεύθυνση πρέπει να είναι προσβάσιμη από το διαδίκτυο μέσω HTTPS — το Shopify δεν παραδίδει σε {localhost} ή σε τομέα {test}. Κάθε παράδοση καταγράφεται μία φορά, οπότε οι επαναλήψεις του Shopify δεν μπορούν να δημιουργήσουν διπλότυπη παραγγελία, και μια αποτυχημένη μπορεί να επαναληφθεί. Οι παραδόσεις απορρίπτονται μέχρι να αποθηκευτεί το μυστικό υπογραφής από το βήμα 1.',
'Shopify_G_Instant_Out' => 'Άμεση αποστολή αποθέματος — το ERP → το κατάστημα',
'Shopify_G_Setting_Missed' => 'Αυτή είναι η ρύθμιση που ξεχνούν οι περισσότεροι',
'Shopify_G_Pos_Not_Auto' => 'Μια πώληση POS {not} φτάνει στο Shopify από μόνη της. Αν μείνει ανενεργό, το κατάστημα το μαθαίνει μόνο στο επόμενο βήμα αποστολής αποθέματος — και σε αυτό το διάστημα μπορεί να πουλήσει μια μονάδα που έχετε ήδη πουλήσει στο ταμείο.',
'Shopify_G_Not' => 'ΔΕΝ',
'Shopify_G_Tick_Push' => 'Επιλέξτε {setting} στο {where}. Αυτή είναι όλη η ρύθμιση — χωρίς worker, χωρίς cron. Κάθε πώληση, επιστροφή και προσαρμογή στέλνει τότε ενημέρωση μόνο για αυτά τα προϊόντα, αμέσως μετά την αποθήκευση της πώλησης, και μια πώληση είκοσι γραμμών κοστίζει μία αποστολή, όχι είκοσι. Το ταμείο δεν περιμένει ποτέ.',
'Shopify_G_This_Store' => 'Αυτό το κατάστημα:',
'Shopify_G_Push_On' => 'ενεργό — το απόθεμα αποστέλλεται σε κάθε αλλαγή',
'Shopify_G_Push_Off' => 'ανενεργό — το απόθεμα μόνο σύμφωνα με το πρόγραμμα',
'Shopify_G_Push_Note' => 'Αποστέλλονται μόνο προϊόντα που έχουν ήδη αντιστοίχιση Shopify και μόνο κινήσεις στην αποθήκη αυτού του καταστήματος. Οι μαζικές λειτουργίες — διαγραφή προϊόντος, επαναφορά αποθήκης — γράφουν απόθεμα χωρίς να ενεργοποιούν συμβάν, γεγονός που αποτελεί έναν λόγο να διατηρήσετε και το προγραμματισμένο βήμα αποθέματος.',
'Shopify_G_Nothing_Install' => 'Τίποτα άλλο για εγκατάσταση',
'Shopify_G_No_Worker_Note' => 'Κανένα από τα δύο μισά δεν χρειάζεται queue worker ή καταχώριση cron. Ένα εισερχόμενο webhook διεκπεραιώνεται στο αίτημα που κάνει το Shopify· μια εξερχόμενη αποστολή αποθέματος εκτελείται στην ίδια διεργασία που εξυπηρέτησε την πώληση, {after} την αποστολή της απάντησης — οπότε το ταμείο δεν περιμένει ποτέ το Shopify, και ένα κατάστημα που σταματά να απαντά εγκαταλείπεται μετά από δέκα δευτερόλεπτα και αφήνεται για την επόμενη προγραμματισμένη αποστολή αποθέματος.',
'Shopify_G_After' => 'μετά',
'Shopify_G_Artisan_Note' => 'Μία εξαίρεση: μια αλλαγή αποθέματος από εντολή artisan δεν έχει απάντηση μετά την οποία να εκτελεστεί, οπότε τοποθετείται στην ουρά {queue}. Αν θέλετε να αποστέλλονται κι αυτές άμεσα, αδειάστε αυτή την ουρά:',
'Shopify_G_On_Schedule' => 'Με χρονοπρογραμματισμό',
'Shopify_G_On_Lower' => 'ενεργό',
'Shopify_G_Off_Lower' => 'ανενεργό',
'Shopify_G_Scheduled_Lead' => 'Όλα ελέγχονται ξανά κατά διαστήματα, και προς τις δύο κατευθύνσεις. Πιο αργό από τον πραγματικό χρόνο, αλλά είναι αυτό που αποστέλλει απόθεμα σε καταστήματα που δεν χρησιμοποιούν άμεση αποστολή, αυτό που πιάνει ένα χαμένο webhook και ο μόνος τρόπος να μεταφερθεί ένας ολόκληρος κατάλογος.',
'Shopify_G_Cron_Entry' => 'Η καταχώριση cron',
'Shopify_G_Cron_Entry_Desc' => 'Τίποτα προγραμματισμένο δεν εκτελείται χωρίς αυτήν. Μία γραμμή, μόνο για αυτή την ενότητα — προσθέστε την δίπλα σε ό,τι άλλο έχετε επιλέξει να προγραμματίσετε:',
'Shopify_G_Cron_Note' => 'Κάθε πέντε λεπτά είναι η μικρότερη συχνότητα που μπορεί να χρησιμοποιήσει ένα πλάνο, επειδή τα πέντε λεπτά είναι το συντομότερο διάστημα βήματος. Μια αραιότερη καταχώριση απλώς γίνεται το κατώτατο όριο — με {example}, ένα βήμα ρυθμισμένο στα 5 λεπτά εκτελείται κάθε 15. Στα Windows χρησιμοποιήστε τον Χρονοπρογραμματιστή εργασιών: πρόγραμμα {program}, ορίσματα {args}, με έναρξη στο {dir}.',
'Shopify_G_Switch_On_Plan' => 'Ενεργοποιήστε το και επιλέξτε το πλάνο',
'Shopify_G_Plan_Desc' => '{where} Ο διακόπτης αποφασίζει αν το cron μπορεί να ενεργήσει καθόλου· το πλάνο αποφασίζει τι κάνει. Ένα {step} είναι μία οντότητα σε μία κατεύθυνση με δικό του διάστημα — {first}, {second}. Το προεπιλεγμένο διάστημα χρησιμοποιείται από κάθε βήμα που αφήνει κενό το δικό του πεδίο.',
'Shopify_G_Step_Lower' => 'βήμα',
'Shopify_G_Plan_Note' => 'Αφήστε το πλάνο κενό και το κατάστημα λαμβάνει παραγγελίες και αποστέλλει απόθεμα στο προεπιλεγμένο διάστημα, κάτι που θέλουν τα περισσότερα καταστήματα. Οι παραγγελίες είναι μόνο λήψης: το Shopify είναι εκεί όπου ο πελάτης κάνει μια παραγγελία.',
'Shopify_G_Schedule_On' => 'χρονοπρογραμματισμός ενεργός',
'Shopify_G_Schedule_Off' => 'χρονοπρογραμματισμός ανενεργός — μόνο χειροκίνητα',
'Shopify_G_When_Step_Runs' => 'Πότε εκτελείται πραγματικά ένα βήμα',
'Shopify_G_When_Note' => 'Ένα βήμα είναι προς εκτέλεση όταν το ίδιο βήμα {started} τελευταία φορά πριν από περισσότερο χρόνο από το διάστημά του, όπως προκύπτει από το ιστορικό εκτελέσεων. Έτσι ένας συγχρονισμός που ξεκινάτε χειροκίνητα μεταθέτει τον επόμενο αυτόματο, και ένα βήμα που αποτυγχάνει συνεχώς επαναλαμβάνεται στο διάστημά του αντί σε κάθε κύκλο. Η Επισκόπηση του καταστήματος δείχνει την τελευταία εκτέλεση κάθε βήματος, την επόμενη ώρα εκτέλεσης και τον λόγο που είναι μπλοκαρισμένο όταν είναι. Εκτελέστε την πρώτη αποστολή καταλόγου χειροκίνητα — με {dryRun} πρώτα — πριν τη βάλετε σε χρονοπρογραμματισμό.',
'Shopify_G_Started_Lower' => 'ξεκίνησε',
'Shopify_G_Where_Setting' => 'Πού βρίσκεται κάθε ρύθμιση',
'Shopify_G_Where_Setting_Note' => 'Όλα αυτά βρίσκονται σε ένα υπάρχον κατάστημα: {path} και στη συνέχεια το μολύβι (ή {edit} στη σελίδα του ίδιου του καταστήματος).',
'Shopify_G_Product_Images' => 'Εικόνες προϊόντων',
'Shopify_G_Img_1' => 'Οι εικόνες αποστέλλονται μαζί με το προϊόν σε μια {push} — πρώτα η κύρια εικόνα, μετά η συλλογή και μετά μία για κάθε παραλλαγή που έχει δική της, έως πενήντα.',
'Shopify_G_Products_Push' => 'αποστολή προϊόντων',
'Shopify_G_Img_2' => 'Η εικόνα μιας παραλλαγής μεταφορτώνεται με το προϊόν και στη συνέχεια {assigned}, που είναι ο τρόπος που το μοντελοποιεί το Shopify: μια παραλλαγή δείχνει σε μία από τις εικόνες του προϊόντος. Μια παραλλαγή που επαναχρησιμοποιεί την κύρια εικόνα δεν τη μεταφορτώνει δύο φορές.',
'Shopify_G_Assigned' => 'ανατίθεται σε αυτή την παραλλαγή',
'Shopify_G_Img_3' => 'Μια εικόνα αποθηκευμένη ως αρχείο {uploaded} στο Shopify, δεν συνδέεται, οπότε λειτουργεί ακόμη και όταν αυτή η εγκατάσταση δεν είναι προσβάσιμη από το διαδίκτυο. Μια εικόνα που προστέθηκε ως επικολλημένος σύνδεσμος παραδίδεται στο Shopify ως αυτό το URL, το οποίο πρέπει να είναι δημόσια προσβάσιμο.',
'Shopify_G_Uploaded' => 'μεταφορτώνεται',
'Shopify_G_Img_4' => 'Αποστέλλονται ξανά μόνο όταν πραγματικά αλλάξουν — μια αποστολή που αλλάζει μόνο μια τιμή αφήνει ανέγγιχτες τις εικόνες του καταστήματος, επειδή η αποστολή τους αντικαθιστά ολόκληρο το σύνολο.',
'Shopify_G_Img_5' => 'Η αφαίρεση μιας εικόνας στο ERP {not} τη διαγράφει στο Shopify. Διαγράψτε την κι εκεί, αλλιώς το κατάστημα συνεχίζει να την εμφανίζει.',
'Shopify_G_Commands' => 'Χρήσιμες εντολές',
'Shopify_G_Command_Copied' => 'Η εντολή αντιγράφηκε',
'Shopify_G_Foot' => 'Κάθε συγχρονισμός γράφει στα {logs} και η Επισκόπηση κάθε καταστήματος δείχνει πότε εκτελέστηκε τελευταία κάθε βήμα, πότε είναι η επόμενη εκτέλεση και τι το μπλοκάρει όταν κάτι το μπλοκάρει. Εκεί πρέπει να κοιτάξετε πρώτα όταν ένας συγχρονισμός δεν έκανε αυτό που περιμένατε.',
'Shopify_G_Covers' => 'Καλύπτει',
'Shopify_G_Covers_Rt' => 'Παραγγελίες και αλλαγές που γίνονται στο Shopify· απόθεμα που φεύγει από το ERP (πώληση POS, επιστροφή, προσαρμογή)',
'Shopify_G_Covers_Sch' => 'Τα πάντα, και προς τις δύο κατευθύνσεις — συμπεριλαμβανομένων των αποστολών καταλόγου και όσων έχασε η γρήγορη διαδρομή',
'Shopify_G_Speed' => 'Ταχύτητα',
'Shopify_G_Speed_Rt' => 'Δευτερόλεπτα',
