'Shopify_G_Needs' => 'Απαιτεί',
'Shopify_G_Needs_Rt' => 'Μια δημόσια διεύθυνση HTTPS και το μυστικό υπογραφής για τα εισερχόμενα webhooks. Το εξερχόμενο απόθεμα δεν χρειάζεται τίποτα απολύτως',
