'StoreAdm_Eg' => 'π.χ. {example}',
'StoreAdm_Stock_Required_Available' => '{name}: Απαιτούνται {need} — Διαθέσιμα {have}',
'StoreAdm_PG_Intro_Msg' => 'Τα PayPal, Paystack, Flutterwave, Razorpay, bKash και SSLCommerz χρησιμοποιούνται μόνο στην ολοκλήρωση αγοράς του ΗΛΕΚΤΡΟΝΙΚΟΥ ΚΑΤΑΣΤΗΜΑΤΟΣ.',
'StoreAdm_PG_Intro_Desc' => 'Τα κλειδιά Stripe είναι κοινά για όλο το σύστημα (η διαχείριση και το ηλεκτρονικό κατάστημα χρησιμοποιούν την ίδια ενοποίηση Stripe). Κάθε καρτέλα ενεργοποιεί ή απενεργοποιεί τη μέθοδό της για την ολοκλήρωση αγοράς του ηλεκτρονικού καταστήματος· οι Πληρωμές εκτός σύνδεσης περιέχουν τις μεθόδους που πληρώνονται εκτός συστήματος.',
'StoreAdm_PG_Used_By_Store_Only' => 'Χρησιμοποιείται μόνο στην ολοκλήρωση αγοράς του ηλεκτρονικού καταστήματος',
'StoreAdm_PG_Gw_Key' => 'Κλειδί {gw}',
'StoreAdm_PG_Gw_Secret' => 'Μυστικό {gw}',
'StoreAdm_PG_Cards_Off' => 'Οι πληρωμές με κάρτα είναι απενεργοποιημένες',
'StoreAdm_PG_Cards_Off_Desc' => 'Τα κλειδιά σας διατηρούνται — η ολοκλήρωση αγοράς του ηλεκτρονικού καταστήματος απλώς σταματά να προσφέρει την επιλογή κάρτας μέχρι να την ενεργοποιήσετε ξανά.',
'StoreAdm_PG_No_Stripe_Key' => 'Δεν υπάρχει αποθηκευμένο κλειδί Stripe',
'StoreAdm_PG_No_Stripe_Key_Desc' => 'Εισαγάγετε το κλειδί και το secret του Stripe για να αρχίσετε να δέχεστε πληρωμές με κάρτα στο ηλεκτρονικό κατάστημα.',
'StoreAdm_PG_Gw_Client_Id' => 'Client ID {gw}',
'StoreAdm_PG_Gw_Client_Secret' => 'Client Secret {gw}',
'StoreAdm_PG_Sandbox' => 'Sandbox (λειτουργία δοκιμής)',
'StoreAdm_PG_Sandbox_Paypal_Hint' => 'Το ΕΝΕΡΓΟ χρησιμοποιεί το {sandbox} με διαπιστευτήρια sandbox· απενεργοποιήστε το για χρέωση πραγματικών λογαριασμών στο {live}.',
'StoreAdm_PG_Gw_Webhook_Id_Opt' => '{gw} Webhook ID (προαιρετικό)',
'StoreAdm_PG_Paypal_Webhook_Hint' => 'Εφεδρεία για πληρωμές των οποίων η ανακατεύθυνση του προγράμματος περιήγησης δεν ολοκληρώνεται, καθώς και για επιστροφές χρημάτων/αμφισβητήσεις. Καταχωρίστε ένα webhook στο {site} που δείχνει στο παρακάτω URL (συμβάντα: {events}) και επικολλήστε εδώ το Webhook ID του.',
'StoreAdm_PG_Webhook_Url' => 'Webhook URL:',
'StoreAdm_PG_Gw_Disabled' => 'Το {gw} είναι απενεργοποιημένο',
'StoreAdm_PG_Paypal_Disabled_Desc' => 'Ενεργοποιήστε το PayPal και εισαγάγετε το Client ID και το Secret της REST εφαρμογής σας (από το {site}) για να μπορούν οι πελάτες να πληρώνουν με PayPal στην ολοκλήρωση αγοράς του ηλεκτρονικού καταστήματος.',
'StoreAdm_PG_Gw_Public_Key' => 'Δημόσιο κλειδί {gw}',
'StoreAdm_PG_Gw_Secret_Key' => 'Μυστικό κλειδί {gw}',
'StoreAdm_PG_Paystack_Test_Live' => 'Η λειτουργία δοκιμής ή παραγωγής καθορίζεται από το ζεύγος κλειδιών: τα κλειδιά {test} λειτουργούν σε λειτουργία δοκιμής, τα κλειδιά {live} χρεώνουν πραγματικές κάρτες — δεν υπάρχει ξεχωριστός διακόπτης sandbox.',
'StoreAdm_PG_Paystack_Webhook_Url' => 'Webhook URL (προαιρετική εφεδρεία — ορίστε το στο Settings → API Keys & Webhooks στον πίνακα ελέγχου Paystack· τα αιτήματα επαληθεύονται με HMAC με το secret key σας):',
'StoreAdm_PG_Paystack_Disabled_Desc' => 'Ενεργοποιήστε το Paystack και εισαγάγετε το Public και το Secret key σας (από το {site} → Settings → API Keys) για να δέχεστε κάρτες, τραπεζικές μεταφορές και mobile money στην ολοκλήρωση αγοράς του ηλεκτρονικού καταστήματος.',
'StoreAdm_PG_Secret_Hash_Opt' => 'Secret Hash (webhooks, προαιρετικό)',
'StoreAdm_PG_Flutterwave_Hash_Hint' => 'Το Secret Hash που ορίσατε στο Settings → Webhooks στον πίνακα ελέγχου Flutterwave· τα εισερχόμενα webhooks απορρίπτονται εκτός αν η κεφαλίδα {header} ταιριάζει.',
'StoreAdm_PG_Flutterwave_Info' => 'Χρησιμοποιεί το Flutterwave v3 API με κλασικά κλειδιά. Η λειτουργία δοκιμής ή παραγωγής καθορίζεται από το ζεύγος κλειδιών ({keys} έναντι κλειδιών παραγωγής) — δεν υπάρχει ξεχωριστός διακόπτης sandbox. Το νόμισμα του καταστήματος πρέπει να είναι ενεργοποιημένο στον λογαριασμό σας Flutterwave.',
'StoreAdm_PG_Flutterwave_Webhook_Url' => 'Webhook URL (προαιρετική εφεδρεία — ορίστε το μαζί με το παραπάνω Secret Hash στον πίνακα ελέγχου Flutterwave):',
'StoreAdm_PG_Flutterwave_Disabled_Desc' => 'Ενεργοποιήστε το Flutterwave και εισαγάγετε τα v3 Public και Secret keys σας (από το {site} → Settings → API) για να δέχεστε κάρτες, mobile money και τραπεζικές μεταφορές στην ολοκλήρωση αγοράς του ηλεκτρονικού καταστήματος.',
'StoreAdm_PG_Gw_Key_Id' => 'Key ID {gw}',
'StoreAdm_PG_Gw_Key_Secret' => 'Key Secret {gw}',
'StoreAdm_PG_Webhook_Secret_Opt' => 'Webhook Secret (προαιρετικό)',
'StoreAdm_PG_Razorpay_Secret_Hint' => 'Το secret που ορίζετε κατά τη δημιουργία του webhook στον πίνακα ελέγχου Razorpay· τα εισερχόμενα συμβάντα επαληθεύονται με HMAC έναντι αυτού και απορρίπτονται διαφορετικά.',
'StoreAdm_PG_Razorpay_Info' => 'Χρησιμοποιεί τα Razorpay Payment Links (κάρτες, UPI, netbanking, πορτοφόλια). Η λειτουργία δοκιμής ή παραγωγής καθορίζεται από το ζεύγος κλειδιών ({keys}) — δεν υπάρχει ξεχωριστός διακόπτης sandbox.',
'StoreAdm_PG_Razorpay_Webhook_Url' => 'Webhook URL (προαιρετική εφεδρεία — καταχωρίστε το με το παραπάνω secret στο Settings → Webhooks· συμβάντα: {events}):',
'StoreAdm_PG_Razorpay_Disabled_Desc' => 'Ενεργοποιήστε το Razorpay και εισαγάγετε το Key ID και το Key Secret σας (από το {site} → Settings → API Keys) για να δέχεστε κάρτες, UPI, netbanking και πορτοφόλια στην ολοκλήρωση αγοράς του ηλεκτρονικού καταστήματος.',
'StoreAdm_PG_Gw_App_Key' => 'App Key {gw}',
'StoreAdm_PG_Gw_App_Secret' => 'App Secret {gw}',
'StoreAdm_PG_Gw_Username' => '{gw} Όνομα χρήστη',
'StoreAdm_PG_Gw_Password' => '{gw} Κωδικός πρόσβασης',
