'StoreAdm_PG_Bkash_Info' => 'Χρησιμοποιεί το bKash Tokenized Checkout (διαπιστευτήρια εμπόρου από την πύλη εμπόρων bKash). Το bKash χρεώνει μόνο σε BDT — η επιλογή εμφανίζεται στην ολοκλήρωση αγοράς μόνο όσο το ενεργό νόμισμα του καταστήματος είναι BDT.',
