'Cr_Guide_S_cancelled' => 'Η κράτηση ακυρώθηκε.',
'Cr_Guide_T_Booking' => 'Κράτηση παραγγελιών',
'Cr_Guide_B_Booking' => 'Η Αποστολή σε courier συμπληρώνει τη φόρμα από την πώληση: παραλήπτη, διεύθυνση, το υπόλοιπο οφειλής ως αντικαταβολή και το βάρος των προϊόντων. Οι courier με δικές τους λίστες πόλεων εμφανίζουν επιλογέα, και η επιλογή σας απομνημονεύεται για εκείνη την πόλη. Οι συγκεντρωτικές πλατφόρμες, οι DHL, FedEx, UPS και Lalamove προσφέρουν Σύγκριση τιμών: επιλέξτε μια τιμή και η Κράτηση την αγοράζει. Πολλές πωλήσεις μπορούν να κρατηθούν μαζί από τη λίστα πωλήσεων.',
'Cr_Guide_T_Cod' => 'Αντικαταβολή',
'Cr_Guide_B_Cod' => 'Ένα δέμα με αντικαταβολή περνά από «Δεν έχει εισπραχθεί» σε «Εισπράχθηκε από τον courier» (με την παράδοση) και σε «Αποδόθηκε σε εσάς». Οι courier που αναφέρουν αποδόσεις ολοκληρώνουν μόνοι τους το τελευταίο βήμα· για τους υπόλοιπους χρησιμοποιήστε την Ενημέρωση αντικαταβολής. Με λογαριασμό επιλεγμένο στις Ρυθμίσεις courier, μια απόδοση καταχωρίζεται ως πληρωμή στην πώληση. Οι χρεώσεις courier μπορούν να αποθηκευτούν ως έξοδο μόλις ολοκληρωθεί ένα δέμα.',
'Cr_Guide_T_Returns' => 'Επιστρεφόμενα δέματα',
'Cr_Guide_B_Returns' => 'Από προεπιλογή, ένα επιστρεφόμενο δέμα περιμένει στις Αποστολές courier, στην ενότητα Επιστροφές προς έλεγχο. Η Επαναφορά στο απόθεμα δημιουργεί επιστροφή πώλησης για ολόκληρη την παραγγελία και επαναφέρει τα είδη στο απόθεμα· η Απόρριψη δεν επαναφέρει τίποτα, για κατεστραμμένα ή χαμένα δέματα. Εναλλακτικά, οι Ρυθμίσεις courier μπορούν να κάνουν αυτόματη επαναφορά στο απόθεμα.',
'Cr_Guide_T_Customers' => 'Μηνύματα πελατών και σελίδα παρακολούθησης',
'Cr_Guide_B_Customers' => 'Οι ειδοποιήσεις πελατών στις Ρυθμίσεις courier στέλνουν SMS, email ή WhatsApp στις καταστάσεις που επιλέγετε, μία φορά ανά δέμα, με το δικό σας κείμενο. Η σελίδα παρακολούθησης στο ηλεκτρονικό σας κατάστημα επιτρέπει στους πελάτες να παρακολουθούν ένα δέμα με τον αριθμό παρακολούθησης ή με τον αριθμό παραγγελίας και το τηλέφωνο. Οι πελάτες που επιστρέφουν συχνά δέματα λαμβάνουν σήμανση κινδύνου επιστροφής κατά την κράτηση.',
'Cr_Guide_T_Labels' => 'Ετικέτες',
'Cr_Guide_B_Labels' => 'Η Εκτύπωση ετικέτας δίνει την ετικέτα του ίδιου του courier όταν εκδίδει (PDF, σύνδεσμο ή εικόνα), διαφορετικά μια ετικέτα Stocky με το barcode παρακολούθησης και το ποσό προς είσπραξη. Επιτρέψτε τα αναδυόμενα παράθυρα για αυτόν τον ιστότοπο για να εκτυπώσετε. Οι DHL, FedEx και UPS δίνουν την ετικέτα τους μόνο μία φορά, κατά την κράτηση, και το Stocky τη διατηρεί για επανεκτυπώσεις.',
'Cr_Guide_T_Faq' => 'Αντιμετώπιση προβλημάτων',
'Cr_Guide_Q_Test' => 'Ο έλεγχος σύνδεσης αποτυγχάνει',
'Cr_Guide_A_Test' => 'Τα κλειδιά δοκιμαστικής λειτουργίας αντιστοιχούν στη Δοκιμαστική λειτουργία και τα παραγωγικά κλειδιά στην Παραγωγική· είναι διαφορετικά. Ανοίξτε τα Αρχεία καταγραφής courier και διαβάστε την απάντηση του courier για τον ακριβή λόγο.',
'Cr_Guide_Q_City' => 'Ο courier απορρίπτει την πόλη ή τη διεύθυνση',
'Cr_Guide_A_City' => 'Επιλέξτε την πόλη από τη λίστα πόλεων του courier στη φόρμα κράτησης· οι courier δέχονται μόνο τις δικές τους ονομασίες. Οι courier που λειτουργούν με ταχυδρομικές διευθύνσεις χρειάζονται επίσης τον νομό, τον ταχυδρομικό κώδικα και τον διψήφιο κωδικό χώρας.',
'Cr_Guide_Q_Webhook' => 'Οι καταστάσεις δεν αλλάζουν από μόνες τους',
'Cr_Guide_A_Webhook' => 'Για τους courier που στέλνουν ενημερώσεις, ελέγξτε ότι το webhook URL είναι καταχωρισμένο στον courier: τα Αρχεία καταγραφής courier εμφανίζουν κάθε ενημέρωση που ελήφθη ή τον λόγο απόρριψής της (για παράδειγμα λάθος μυστικό κλειδί). Οι υπόλοιποι courier ελέγχονται σύμφωνα με το πρόγραμμα στις Ρυθμίσεις courier, και ο Έλεγχος κατάστασης τώρα ρωτά αμέσως.',
'Cr_Guide_Q_Stuck' => 'Μια αποστολή εμφανίζει σφάλμα ελέγχου κατάστασης',
'Cr_Guide_A_Stuck' => 'Ο courier απέρριψε τους τελευταίους ελέγχους· ο λόγος εμφανίζεται στην αποστολή και στα Αρχεία καταγραφής courier. Μετά από επανειλημμένες αποτυχίες μια αποστολή δεν ελέγχεται πλέον αυτόματα: διορθώστε την αιτία και, στη συνέχεια, χρησιμοποιήστε τον Έλεγχο κατάστασης τώρα.',
'Cr_Guide_Q_Label' => 'Δεν ανοίγει τίποτα κατά την εκτύπωση ετικέτας',
'Cr_Guide_A_Label' => 'Το πρόγραμμα περιήγησης απέκλεισε το αναδυόμενο παράθυρο. Επιτρέψτε τα αναδυόμενα παράθυρα για αυτόν τον ιστότοπο και δοκιμάστε ξανά.',
'Cr_Guide_Q_Cod' => 'Μια απόδοση αντικαταβολής δεν καταχωρίστηκε στην πώληση',
'Cr_Guide_A_Cod' => 'Στις Ρυθμίσεις courier, η αντικαταβολή χρειάζεται τον διακόπτη ενεργοποιημένο και επιλεγμένο λογαριασμό. Χωρίς λογαριασμό, οι αποδόσεις απλώς σημειώνονται ως αποδοθείσες.',
