'Sec_Two_Factor' => 'Έλεγχος ταυτότητας δύο παραγόντων',
'Sec_2fa_Require' => 'Απαίτηση ελέγχου ταυτότητας δύο παραγόντων',
'Sec_2fa_Require_Help' => 'Το προσωπικό πρέπει να εισάγει έναν κωδικό από εφαρμογή ελέγχου ταυτότητας μετά τον κωδικό πρόσβασης. Ο καθένας μπορεί να τον ενεργοποιήσει για τον εαυτό του από το προφίλ του· αυτή η επιλογή τον κάνει υποχρεωτικό. Οι χρήστες που δεν τον έχουν θα καθοδηγηθούν στη ρύθμιση κατά την επόμενη σύνδεσή τους.',
'Sec_2fa_Stats' => ':enabled από :total ενεργούς χρήστες τον έχουν ενεργοποιημένο',
