'Sec_2fa_Roles_Help' => 'Αφήστε κενό για να απαιτείται από κάθε χρήστη ή επιλέξτε τους ρόλους που πρέπει να τον χρησιμοποιούν.',
'Sec_2fa_All_Users' => 'Όλοι οι χρήστες',
'Sec_2fa_Trust' => 'Απομνημόνευση αξιόπιστων συσκευών',
'Sec_2fa_Trust_Help' => 'Προσφέρει την επιλογή «Να μην ερωτηθώ ξανά σε αυτή τη συσκευή» στην οθόνη κωδικού. Η απενεργοποίηση ή η επαναφορά του 2FA διαγράφει όλες τις αξιόπιστες συσκευές.',
