'Tfa_Since' => 'από :date',
'Tfa_On_Help' => 'Κατά τη σύνδεση ζητείται ένας κωδικός από την εφαρμογή ελέγχου ταυτότητας μετά τον κωδικό πρόσβασης.',
'Tfa_Off_Help' => 'Προσθέστε ένα δεύτερο βήμα σύνδεσης: έναν 6ψήφιο κωδικό από μια εφαρμογή ελέγχου ταυτότητας στο τηλέφωνό σας, όπως Google Authenticator, Microsoft Authenticator ή Authy.',
'Tfa_Codes_Left' => 'Υπόλοιποι κωδικοί ανάκτησης: :count',
'Tfa_Required_Notice' => 'Ο διαχειριστής σας απαιτεί έλεγχο ταυτότητας δύο παραγόντων. Αν δεν τον ενεργοποιήσετε τώρα, θα σας ζητηθεί να τον ρυθμίσετε στην επόμενη σύνδεσή σας.',
