'Tfa_Continue' => 'Συνέχεια',
'Tfa_Step_Install' => 'Εγκαταστήστε μια εφαρμογή ελέγχου ταυτότητας στο τηλέφωνό σας.',
'Tfa_Step_Scan' => 'Σαρώστε αυτόν τον κωδικό QR ή πληκτρολογήστε το κλειδί παρακάτω.',
'Tfa_Step_Confirm' => 'Εισαγάγετε τον 6ψήφιο κωδικό που εμφανίζει η εφαρμογή.',
'Tfa_Enter_Code' => 'Εισαγάγετε τον 6ψήφιο κωδικό από την εφαρμογή.',
'Tfa_Qr_Failed' => 'Ο κωδικός QR δεν είναι διαθέσιμος — πληκτρολογήστε το κλειδί.',
'Tfa_Copy' => 'Αντιγραφή',
'Tfa_Copied' => 'Αντιγράφηκε',
'Tfa_Download' => 'Λήψη',
'Tfa_Done' => 'Τέλος',
'Tfa_Codes_Save' => 'Αποθηκεύστε αυτούς τους κωδικούς ανάκτησης σε ασφαλές μέρος. Ο καθένας σας συνδέει μία φορά αν χάσετε το τηλέφωνό σας. Δεν θα εμφανιστούν ξανά.',
'Tfa_Reset' => 'Επαναφορά 2FA',
'Tfa_Reset_Title' => 'Επαναφορά ελέγχου ταυτότητας δύο παραγόντων;',
'Tfa_Reset_Help' => 'Ο/Η :name θα συνδέεται μόνο με τον κωδικό πρόσβασης και στη συνέχεια μπορεί να ρυθμίσει ξανά την εφαρμογή ελέγχου ταυτότητας. Κάντε το μόνο αφού επιβεβαιώσετε ποιος το ζητά.',
'Tfa_Guide_Lead' => 'Ο έλεγχος ταυτότητας δύο παραγόντων (2FA) προσθέτει ένα δεύτερο βήμα στη σύνδεση: μετά τον κωδικό πρόσβασης, το προσωπικό πληκτρολογεί έναν 6ψήφιο κωδικό από μια εφαρμογή ελέγχου ταυτότητας στο τηλέφωνό του. Ένας κλεμμένος ή μαντεμένος κωδικός πρόσβασης δεν αρκεί πλέον για την είσοδο.',
'Tfa_Guide_State_Required' => 'Απαιτείται',
'Tfa_Guide_State_Optional' => 'Όχι — προαιρετικό για όλους',
'Tfa_Guide_State_Trust' => 'Αξιόπιστες συσκευές',
'Tfa_Guide_State_Users' => 'Χρήστες με ενεργό 2FA',
'Tfa_Guide_Staff_Title' => 'Για κάθε μέλος του προσωπικού',
'Tfa_Guide_App_Title' => 'Εγκαταστήστε μια εφαρμογή ελέγχου ταυτότητας',
'Tfa_Guide_App_Text' => 'Λειτουργεί οποιαδήποτε εφαρμογή υποστηρίζει τυπικούς 6ψήφιους κωδικούς (TOTP). Είναι δωρεάν και λειτουργούν χωρίς σύνδεση:',
'Tfa_Guide_Enable_Title' => 'Ενεργοποιήστε τον από το προφίλ',
'Tfa_Guide_Enable_1' => 'Ανοίξτε το Προφίλ (μενού avatar επάνω δεξιά) και βρείτε την κάρτα "Έλεγχος ταυτότητας δύο παραγόντων".',
'Tfa_Guide_Enable_2' => 'Κάντε κλικ στο "Ενεργοποίηση" και επιβεβαιώστε με τον τρέχοντα κωδικό πρόσβασης.',
'Tfa_Guide_Enable_3' => 'Σαρώστε τον κωδικό QR με την εφαρμογή ή πληκτρολογήστε το κλειδί που εμφανίζεται από κάτω.',
'Tfa_Guide_Enable_4' => 'Εισαγάγετε τον 6ψήφιο κωδικό που εμφανίζει η εφαρμογή για να ολοκληρώσετε.',
'Tfa_Guide_Open_Profile' => 'Άνοιγμα του προφίλ μου',
'Tfa_Guide_Codes_Title' => 'Αποθηκεύστε τους κωδικούς ανάκτησης',
'Tfa_Guide_Codes_Text' => 'Αμέσως μετά τη ρύθμιση, εμφανίζονται μία φορά 8 κωδικοί ανάκτησης. Ο καθένας αντικαθιστά τον κωδικό του τηλεφώνου μία μόνο φορά — σε περίπτωση απώλειας, βλάβης ή επαναφοράς του τηλεφώνου. Κατεβάστε ή αντιγράψτε τους και φυλάξτε τους σε ασφαλές μέρος, μακριά από το τηλέφωνο.',
'Tfa_Guide_Codes_Note' => 'Σας τελειώνουν; Το "Νέοι κωδικοί ανάκτησης" στο προφίλ αντικαθιστά ολόκληρο το σύνολο· οι παλιοί παύουν να λειτουργούν.',
'Tfa_Guide_Signin_Title' => 'Σύνδεση',
'Tfa_Guide_Signin_Text' => 'Μετά το email και τον κωδικό πρόσβασης, η σελίδα σύνδεσης ζητά τον τρέχοντα κωδικό από την εφαρμογή. Οι κωδικοί αλλάζουν κάθε 30 δευτερόλεπτα και ο καθένας λειτουργεί μία φορά.',
'Tfa_Guide_Signin_Trust' => 'Η επιλογή "Να μην ερωτηθώ ξανά σε αυτή τη συσκευή" παραλείπει τον κωδικό σε αυτόν τον browser για :days ημέρες.',
'Tfa_Guide_Signin_Recovery' => 'Δεν έχετε το τηλέφωνο μαζί σας; Κάντε κλικ στο "Χρήση κωδικού ανάκτησης" και πληκτρολογήστε έναν από τους αποθηκευμένους κωδικούς.',
'Tfa_Guide_Admin_Title' => 'Για διαχειριστές',
'Tfa_Guide_Require_Title' => 'Κάντε τον υποχρεωτικό',
'Tfa_Guide_Require_Text' => 'Ενεργοποιήστε την επιλογή "Απαίτηση ελέγχου ταυτότητας δύο παραγόντων" σε αυτή την κάρτα και, στη συνέχεια, επιλέξτε τους ρόλους που πρέπει να τον χρησιμοποιούν — ή αφήστε τη λίστα κενή για όλους τους χρήστες. Κάντε κλικ στην Υποβολή για αποθήκευση.',
'Tfa_Guide_Require_Next' => 'Κανείς δεν αποσυνδέεται. Οι χρήστες που δεν έχουν ακόμη 2FA καθοδηγούνται στη ρύθμιση στη σελίδα σύνδεσης κατά την επόμενη σύνδεσή τους, πριν μπουν, και βλέπουν εκεί τους κωδικούς ανάκτησης.',
'Tfa_Guide_Require_Note' => 'Οι χρήστες για τους οποίους είναι υποχρεωτικός δεν μπορούν να τον απενεργοποιήσουν από το προφίλ τους.',
'Tfa_Guide_Trust_Title' => 'Αξιόπιστες συσκευές',
'Tfa_Guide_Trust_Text' => 'Η επιλογή "Απομνημόνευση αξιόπιστων συσκευών" ορίζει για πόσο καιρό ένας browser μπορεί να παραλείπει τον κωδικό μετά από επιτυχή σύνδεση. Επιλέξτε "Πάντα να ζητείται κωδικός" για κοινόχρηστους ή δημόσιους υπολογιστές, όπως ένα POS στον χώρο του καταστήματος.',
'Tfa_Guide_Trust_Note' => 'Η μείωση του αριθμού συντομεύει και τις ήδη αξιόπιστες συσκευές· η απενεργοποίηση ή η επαναφορά του 2FA τις διαγράφει όλες.',
'Tfa_Guide_Lost_Title' => 'Χαμένο τηλέφωνο χωρίς κωδικούς ανάκτησης',
'Tfa_Guide_Lost_Text' => 'Στη σελίδα Χρήστες, οι χρήστες με 2FA εμφανίζουν "Ενεργό" στη στήλη 2FA. Το κουμπί με την ασπίδα στις Ενέργειες το επαναφέρει: ο χρήστης συνδέεται μόνο με τον κωδικό πρόσβασης και ρυθμίζει ξανά την εφαρμογή (ή του ζητείται να το κάνει, αν είναι υποχρεωτικό).',
'Tfa_Guide_Lost_Warn' => 'Επιβεβαιώστε ποιος το ζητά πριν από την επαναφορά — η επαναφορά αφαιρεί την προστασία που παρέχει το 2FA σε αυτόν τον λογαριασμό.',
'Tfa_Guide_Open_Users' => 'Άνοιγμα Χρηστών',
'Tfa_Guide_Mobile_Title' => 'Εφαρμογή κινητού και API',
'Tfa_Guide_Mobile_Text' => 'Η εφαρμογή κινητού και το endpoint token του API ζητούν τον ίδιο κωδικό. Αν το 2FA είναι υποχρεωτικό για έναν χρήστη που δεν το έχει ρυθμίσει ακόμη, πρέπει να συνδεθεί μία φορά στο web για να το κάνει.',
'Tfa_Guide_Protect_Title' => 'Ενσωματωμένη προστασία',
'Tfa_Guide_Protect_1' => '5 λανθασμένοι κωδικοί μπλοκάρουν την εισαγωγή κωδικού για αυτόν τον χρήστη για 15 λεπτά, ανεξάρτητα από τις παραπάνω ρυθμίσεις κλειδώματος.',
'Tfa_Guide_Protect_2' => 'Κάθε κωδικός και κάθε κωδικός ανάκτησης λειτουργεί μόνο μία φορά.',
'Tfa_Guide_Protect_3' => 'Με ενεργή την επιλογή "Καταγραφή δραστηριότητας σύνδεσης", οι λανθασμένοι κωδικοί εμφανίζονται στη λίστα Δραστηριότητα σύνδεσης ως "Λάθος κωδικός 2FA".',
'Tfa_Guide_Trouble_Title' => 'Αντιμετώπιση προβλημάτων',
'Tfa_Guide_Faq_Clock_Q' => '«Ο κωδικός δεν είναι έγκυρος» με νέο κωδικό',
'Tfa_Guide_Faq_Clock_A' => 'Πιθανότατα το ρολόι του τηλεφώνου δεν είναι σωστό. Οι κωδικοί εξαρτώνται από την ώρα: ορίστε την ημερομηνία και ώρα του τηλεφώνου σε αυτόματη (ώρα δικτύου) και δοκιμάστε τον επόμενο κωδικό.',
'Tfa_Guide_Faq_Phone_Q' => 'Μετάβαση σε νέο τηλέφωνο',
'Tfa_Guide_Faq_Phone_A' => 'Χρησιμοποιήστε τη λειτουργία μεταφοράς της ίδιας της εφαρμογής ελέγχου ταυτότητας ή απενεργοποιήστε το 2FA στο προφίλ και ενεργοποιήστε το ξανά με το νέο τηλέφωνο (αν είναι υποχρεωτικό, ζητήστε από έναν διαχειριστή να το επαναφέρει).',
'Tfa_Guide_Faq_Locked_Q' => '«Πάρα πολλοί μη έγκυροι κωδικοί»',
'Tfa_Guide_Faq_Locked_A' => 'Περιμένετε τον χρόνο που εμφανίζεται (έως 15 λεπτά) ή ζητήστε από έναν διαχειριστή να επαναφέρει το 2FA του χρήστη.',
'Tfa_Guide_Faq_Key_Q' => 'Κανείς με 2FA δεν μπορεί να συνδεθεί μετά από μεταφορά διακομιστή',
'Tfa_Guide_Faq_Key_A' => 'Τα μυστικά 2FA κρυπτογραφούνται με το APP_KEY στο αρχείο .env. Διατηρήστε το ίδιο APP_KEY κατά τη μεταφορά ή την επαναφορά της εφαρμογής· αν άλλαξε, ένας διαχειριστής χωρίς 2FA πρέπει να επαναφέρει τους επηρεαζόμενους χρήστες.',
'Tfa_Guide_Button' => 'Οδηγός',
'Tfa_Guide_Title' => 'Οδηγός ελέγχου ταυτότητας δύο παραγόντων',
'Sec_2fa_Pending' => ':count δεν το έχουν ρυθμίσει ακόμη',
'Sec_2fa_See_Who' => 'Δείτε ποιοι',
'Sec_2fa_Grace_Off' => 'Καμία — ρύθμιση στην επόμενη σύνδεση',
'Sec_2fa_Applied' => ':count χρήστης(-ες) αποσυνδέθηκαν.',
'Tfa_Guide_Rollout_Title' => 'Εφαρμογή σε όλους τους χρήστες',
'Tfa_Guide_Rollout_1' => 'Ενεργοποιήστε το πρώτα για τον δικό σας λογαριασμό (Προφίλ), ώστε να γνωρίζετε τα βήματα.',
'Tfa_Guide_Rollout_2' => 'Ενημερώστε την ομάδα σας ποια εφαρμογή να εγκαταστήσει και ότι η ρύθμιση διαρκεί ένα λεπτό κατά τη σύνδεση.',
'Tfa_Guide_Rollout_3' => 'Ενεργοποιήστε την επιλογή "Απαίτηση ελέγχου ταυτότητας δύο παραγόντων", αφήστε κενό το "Απαιτείται για" (= όλοι οι χρήστες) και προαιρετικά επιλέξτε περίοδο χάριτος. Κάντε κλικ στην Υποβολή.',
'Tfa_Guide_Rollout_4' => 'Κάντε κλικ στο "Αποσύνδεση χρηστών χωρίς 2FA" ώστε όσοι είναι ήδη συνδεδεμένοι να το ρυθμίσουν τώρα αντί σε κάποια μεταγενέστερη σύνδεση. Εσείς παραμένετε συνδεδεμένοι.',
'Tfa_Guide_Rollout_5' => 'Παρακολουθήστε την πρόοδο με τον μετρητή σε αυτή την κάρτα ή με το φίλτρο "Χρειάζεται ρύθμιση" στη σελίδα Χρήστες.',
'Tfa_Guide_Rollout_Note' => 'Με περίοδο χάριτος, η οθόνη ρύθμισης εμφανίζει «Υπενθύμιση αργότερα» μέχρι την προθεσμία· μετά από αυτήν, η ρύθμιση είναι απαραίτητη για τη σύνδεση.',
'Tfa_Guide_Customers_Title' => 'Λογαριασμοί πελατών (κατάστημα και πύλη πελατών)',
'Tfa_Guide_Customers_Text' => 'Οι πελάτες μπορούν επίσης να προστατεύσουν τους δικούς τους λογαριασμούς. Είναι προαιρετικό για κάθε πελάτη και ποτέ υποχρεωτικό: ενεργοποιήστε το από Ρυθμίσεις καταστήματος → Έλεγχος πρόσβασης εγγραφής (ηλεκτρονικό κατάστημα) και Πύλη πελατών → Ρυθμίσεις πύλης (πύλη πελατών).',
'Tfa_Guide_Customers_1' => 'Οι πελάτες το ενεργοποιούν από τον Λογαριασμό μου (κατάστημα) ή το Προφίλ (πύλη).',
'Tfa_Guide_Customers_2' => 'Επιλέγουν κωδικό που αποστέλλεται μέσω email — το πιο εύκολο, χωρίς εφαρμογή — ή εφαρμογή ελέγχου ταυτότητας με κωδικούς ανάκτησης.',
'Tfa_Guide_Customers_3' => 'Οι κωδικοί μέσω email απαιτούν λειτουργικές ρυθμίσεις αλληλογραφίας (Ρυθμίσεις → Ρυθμίσεις αλληλογραφίας). Λήγουν μετά από 10 λεπτά.',
'Tfa_Guide_Customers_4' => 'Η απενεργοποίηση της επιλογής αργότερα σταματά τις νέες ρυθμίσεις· οι πελάτες που ήδη το χρησιμοποιούν συνεχίζουν να ερωτώνται και μπορούν να το απενεργοποιήσουν οι ίδιοι.',
'Tfa_Required_Grace_Notice' => 'Ο διαχειριστής σας απαιτεί έλεγχο ταυτότητας δύο παραγόντων. Μπορείτε να τον αναβάλετε κατά τη σύνδεση έως :date· μετά από αυτό, η ρύθμιση είναι υποχρεωτική.',
'Tfa_Filter_All' => '2FA: όλοι οι χρήστες',
'Tfa_Needs_Setup_Help' => 'Απαιτείται από Ρυθμίσεις συστήματος > Ασφάλεια· θα ζητηθεί ρύθμιση στην επόμενη σύνδεση.',
'Tfa_Needs_Setup' => 'Χρειάζεται ρύθμιση',
'Tfa_Filter_On' => '2FA ενεργό',
'Tfa_Filter_Off' => '2FA ανενεργό',
'Tfa_Filter_Pending' => 'Χρειάζεται ρύθμιση (υποχρεωτικό)',
'Store_Customer_2fa' => 'Επαλήθευση δύο βημάτων',
'Store_Customer_2fa_Help' => 'Επιτρέπει στους πελάτες να προστατεύουν τον λογαριασμό τους με κωδικό που αποστέλλεται μέσω email ή από εφαρμογή ελέγχου ταυτότητας, με ενεργοποίηση από τον Λογαριασμό μου. Προαιρετικό για κάθε πελάτη.',
'Portal_2fa' => 'Επαλήθευση δύο βημάτων',
'Portal_2fa_Help' => 'Επιτρέπει στους πελάτες να προστατεύουν τη σύνδεσή τους στην πύλη με κωδικό που αποστέλλεται μέσω email ή από εφαρμογή ελέγχου ταυτότητας, με ενεργοποίηση από το προφίλ τους. Προαιρετικό για κάθε πελάτη.',
'Two_factor_grace_notice' => 'Υποχρεωτικό από :date. Μπορείτε να το ρυθμίσετε αργότερα έως τότε.',
'Two_factor_remind_later' => 'Υπενθύμιση αργότερα',
'Sec_2fa_Grace' => 'Περίοδος χάριτος',
'Sec_2fa_Grace_Help' => 'Επιτρέπει στους χρήστες να επιλέγουν «Υπενθύμιση αργότερα» στην οθόνη ρύθμισης μέχρι την προθεσμία, ώστε κανείς να μη σταματήσει στη μέση μιας βάρδιας. Υπολογίζεται από τη στιγμή που ενεργοποιήθηκε η απαίτηση.',
'Sec_2fa_Grace_Ends' => 'Η ρύθμιση γίνεται υποχρεωτική στις :date.',
'Sec_2fa_Apply' => 'Εφαρμογή τώρα',
'Sec_2fa_Apply_Help' => 'Όσοι είναι ήδη συνδεδεμένοι ερωτώνται μόνο στην επόμενη σύνδεσή τους, η οποία μπορεί να απέχει μήνες με το «Να με θυμάσαι». Αυτό αποσυνδέει όλους όσους πρέπει να ρυθμίσουν 2FA και δεν το έχουν κάνει, σε κάθε συσκευή, ώστε να το ρυθμίσουν όταν συνδεθούν ξανά. Εσείς παραμένετε συνδεδεμένοι.',
