'Cust_2fa_Reset_Help' => 'Αυτός ο πελάτης θα συνδέεται μόνο με τον κωδικό πρόσβασης και μπορεί να την ενεργοποιήσει ξανά από τον λογαριασμό του. Κάντε το μόνο αφού επιβεβαιώσετε ποιος το ζητά.',
