'Reorder_Safety_Help' => 'Επιπλέον ημέρες αποθέματος που διατηρούνται σε περίπτωση καθυστερήσεων ή μιας φορτωμένης εβδομάδας.',
'Reorder_Coverage' => 'Παραγγελία επαρκής για (ημέρες)',
'Reorder_Coverage_Help' => 'Για πόσες ημέρες πωλήσεων πρέπει να επαρκεί κάθε παραγγελία μόλις παραληφθεί.',
'Reorder_How' => 'Πώς λειτουργούν οι προτάσεις',
'Reorder_How_1' => 'Αναπαραγγελία όταν το απόθεμα + οι ανοιχτές παραγγελίες πέσουν στο: ημερήσιες πωλήσεις × (χρόνος παράδοσης + ημέρες ασφαλείας), και ποτέ κάτω από την ειδοποίηση αποθέματος του προϊόντος.',
'Reorder_How_2' => 'Παραγγέλνεται ποσότητα που καλύπτει τον χρόνο παράδοσης + τις ημέρες ασφαλείας + τις παραπάνω ημέρες. Τα προϊόντα χωρίς πρόσφατες πωλήσεις συμπληρώνονται έως το διπλάσιο της ειδοποίησης αποθέματός τους.',
'Reorder_How_3' => 'Οι ποσότητες είναι στη μονάδα αγοράς, στρογγυλοποιημένες προς τα πάνω στην ελάχιστη παραγγελία και στο πολλαπλάσιο του προϊόντος.',
